const GAME_CSS = "\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  body {\n    background: linear-gradient(135deg, #fef3e2 0%, #fde6c8 100%);\n    font-family: \"PingFang SC\", \"Microsoft YaHei\", \"Helvetica Neue\", sans-serif;\n    display: flex; flex-direction: column; align-items: center;\n    min-height: 100vh; padding: 12px; color: #5a4a3a;\n  }\n  h1 {\n    font-size: 20px; color: #8b5a2b; margin-bottom: 8px;\n    text-shadow: 1px 1px 0 #fff;\n  }\n  #wrap {\n    position: relative; width: 900px; max-width: 100%;\n    border-radius: 14px; overflow: hidden;\n    box-shadow: 0 8px 28px rgba(139,90,43,.25);\n    background: #c5e0a0;\n  }\n  canvas { display: block; width: 100%; height: auto; cursor: pointer; }\n  #overlay {\n    position: absolute; inset: 0; display: none;\n    align-items: center; justify-content: center;\n    background: rgba(60,50,40,.55); backdrop-filter: blur(3px);\n    flex-direction: column; color: #fff; text-align: center;\n  }\n  #overlay.show { display: flex; }\n  #overlay h2 { font-size: 34px; margin-bottom: 8px; text-shadow: 2px 2px 0 rgba(0,0,0,.3); }\n  #overlay p { font-size: 16px; opacity: .9; margin-bottom: 12px; }\n  #ovLeaderboard {\n    max-width: 420px; margin-bottom: 18px; text-align: left;\n    background: rgba(0,0,0,.25); border-radius: 10px; padding: 12px 20px;\n  }\n  #ovLeaderboard h3 { font-size: 16px; color: #ffd24a; margin-bottom: 8px; text-align: center; }\n  #ovLeaderboard .lb-row { font-size: 14px; line-height: 1.8; display: flex; justify-content: space-between; }\n  #ovLeaderboard .lb-row span:first-child { margin-right: 12px; }\n  #ovLeaderboard .lb-note { font-size: 12px; color: #c0a060; text-align: center; margin-top: 8px; }\n  #overlay button {\n    padding: 12px 28px; font-size: 16px; border: none; border-radius: 24px;\n    background: linear-gradient(135deg, #ffb347, #ff8c42); color: #fff;\n    cursor: pointer; font-weight: 600; box-shadow: 0 4px 12px rgba(255,140,66,.4);\n    transition: transform .15s;\n  }\n  #overlay button:hover { transform: scale(1.06); }\n  .tip { font-size: 12px; color: #a08060; margin-top: 8px; text-align: center; }\n  #cheatInput {\n    position: absolute; top: 1.8%; left: 85.3%; width: 12.7%; height: 6.4%;\n    font-size: 14px; text-align: center; box-sizing: border-box;\n    border: 2px solid #8b5a2b; border-radius: 6px;\n    background: rgba(255,255,255,.95); color: #5a4a3a;\n    z-index: 10; display: none; outline: none;\n  }\n";

// 客户端游戏脚本：自包含，所有常量在脚本内部定义。
// window.__SEED__ 由 webview handler 注入；本地预览时为 undefined，回退到 Date.now()。
const GAME_JS = "\n\"use strict\";\n/* ===== 基础工具 ===== */\nconst C = document.getElementById(\"game\");\nconst ctx = C.getContext(\"2d\");\nconst W = C.width, H = C.height;\n\n/* 伪随机数生成器（可种子化，用于回放校验） */\nfunction makeRng(seed){\n  let s = seed >>> 0 || 1;\n  return function(){\n    s = (s * 1664525 + 1013904223) >>> 0;\n    return s / 4294967296;\n  };\n}\nlet rng = makeRng(Date.now() & 0xffffffff);\n\n/* ISO 周数（周一到周日），双端一致；服务端注入 window.__WEEK__ 时也用此算法 */\nfunction isoWeek(d){\n  const date = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));\n  const dayNum = date.getUTCDay() || 7;\n  date.setUTCDate(date.getUTCDate() + 4 - dayNum);\n  const yearStart = new Date(Date.UTC(date.getUTCFullYear(),0,1));\n  const weekNum = Math.ceil((((date - yearStart)/86400000) + 1)/7);\n  return date.getUTCFullYear() + \"W\" + String(weekNum).padStart(2,\"0\");\n}\n/* 每周僵尸组合：由 yearWeek 字符串哈希成种子确定性生成，全球本周相同 */\nfunction weeklyZombieSet(yearWeek){\n  return [\"normal\",\"flag\",\"newspaper\",\"football\",\"screendoor\",\"conehead\",\"buckethead\",\"polevaulter\"];\n}\n\n/* ===== 地图常量（参考 pypvz constants.py） ===== */\nconst COLS = 9;\nconst CELL_W = 78, CELL_H = 88;\nconst GRID_X = 132;\nlet ROWS = 5;\nlet GRID_Y = 122;\nfunction calcGridY(rows){ return 102 + Math.max(0, (H - 122 - rows*CELL_H)) / 2; }\nconst HOUSE_X = GRID_X - 30;\nconst SPAWN_X = GRID_X + COLS * CELL_W + 20;\n\n/* ===== 游戏数值（源自 pypvz constants.py，适配 web 节奏） ===== */\nlet INIT_SUN = 50;\nconst SUN_VALUE = 25;\nconst SUN_BOX_X = W - 110;\nconst SUN_BOX_Y = 28;\nconst SUN_DROP_INTERVAL = 10000;\nconst SUN_LIVE_TIME = 11000;\nconst PEA_INTERVAL = 1400;\nconst PEA_FIRST_DELAY = 700;\nconst BULLET_SPEED = 230;\nconst BULLET_DAMAGE = 20;\nconst SUNFLOWER_INTERVAL = 8000;\nconst SUNFLOWER_FIRST = 5000;\nconst ZOMBIE_SPEED = 14;\nconst ZOMBIE_HEALTH = 270;\nconst ZOMBIE_DAMAGE = 50;\nconst ZOMBIE_ATTACK_INTERVAL = 500;\nconst PLANT_HEALTH = 300;\nconst WALLNUT_HEALTH = 4000;\nconst POTATO_ARM_TIME = 14000;\nconst POTATO_DAMAGE = 1800;\nconst CHERRY_FUSE = 1200;\nconst CHERRY_DAMAGE = 1800;\nlet NUM_FLAGS = 2;\nconst CONEHEAD_HEALTH = 370;\nconst BUCKETHEAD_HEALTH = 1100;\nconst POLE_VAULTER_HEALTH = 500;\nconst NEWSPAPER_HEALTH = 200;\nconst NEWSPAPER_PAPER_HEALTH = 250;\nconst FOOTBALL_HEALTH = 270;\nconst FOOTBALL_HELMET_HEALTH = 1400;\nconst SCREENDOOR_HEALTH = 270;\nconst SCREENDOOR_SHIELD_HEALTH = 1100;\n\n/* ===== 关卡定义（源自 pypvz map.py MAP_DATA，植物解锁参考原版冒险模式） ===== */\nconst LEVELS = [\n  { id:0, title:\"白天 1-5\", sub:\"终极挑战\", rows:5, initSun:50,  flags:3, zombies:[\"normal\",\"conehead\",\"polevaulter\",\"buckethead\"],\n    plants:[\"sunflower\",\"peashooter\",\"repeaterpea\",\"snowpea\",\"chomper\",\"threepeater\",\"wallnut\",\"potatomine\",\"cherrybomb\"] },\n];\n\n/* ===== 僵尸类型定义 ===== */\nconst ZOMBIE_TYPES = {\n  normal:     { hp: ZOMBIE_HEALTH, helmet: 0 },\n  conehead:   { hp: ZOMBIE_HEALTH, helmet: CONEHEAD_HEALTH },\n  buckethead: { hp: ZOMBIE_HEALTH, helmet: BUCKETHEAD_HEALTH },\n  polevaulter:{ hp: POLE_VAULTER_HEALTH, helmet: 0, speed: 1.5 },\n  flag:       { hp: ZOMBIE_HEALTH, helmet: 0 },\n  newspaper:  { hp: NEWSPAPER_HEALTH, helmet: NEWSPAPER_PAPER_HEALTH, speed: 1.0 },\n  football:   { hp: FOOTBALL_HEALTH, helmet: FOOTBALL_HELMET_HEALTH, speed: 1.6 },\n  screendoor: { hp: SCREENDOOR_HEALTH, helmet: SCREENDOOR_SHIELD_HEALTH, speed: 1.0 },\n};\n\n/* ===== 植物定义（数值源自 pypvz constants.py PLANT_CARD_INFO） ===== */\nconst PLANTS = {\n  sunflower:   { name:\"向日葵\",   cost:50,  cd:7500,  hp:PLANT_HEALTH, color:\"#ffc928\" },\n  peashooter:  { name:\"豌豆射手\", cost:100, cd:7500,  hp:PLANT_HEALTH, color:\"#6cbb3c\" },\n  repeaterpea: { name:\"双发豌豆\", cost:200, cd:7500,  hp:PLANT_HEALTH, color:\"#5aa530\" },\n  snowpea:     { name:\"寒冰射手\", cost:175, cd:7500,  hp:PLANT_HEALTH, color:\"#5ab8e0\" },\n  chomper:     { name:\"食人花\",   cost:150, cd:7500,  hp:PLANT_HEALTH, color:\"#9a5ab8\" },\n  threepeater: { name:\"三线豌豆\", cost:325, cd:7500,  hp:PLANT_HEALTH, color:\"#6cbb3c\" },\n  wallnut:     { name:\"坚果墙\",   cost:50,  cd:30000, hp:WALLNUT_HEALTH, color:\"#c98a3a\" },\n  potatomine:  { name:\"土豆地雷\", cost:25,  cd:30000, hp:PLANT_HEALTH, color:\"#b8862b\" },\n  cherrybomb:  { name:\"樱桃炸弹\", cost:150, cd:50000, hp:Infinity, color:\"#e04444\" },\n};\nconst CARD_ORDER = [\"sunflower\",\"peashooter\",\"repeaterpea\",\"snowpea\",\"chomper\",\"threepeater\",\"wallnut\",\"potatomine\",\"cherrybomb\"];\n\n/* ===== 状态 ===== */\nlet state, lastTime, mouse, selected, shovelActive;\nlet waveTimer, waveIndex, zombiesToSpawn, spawnTimer;\nlet sunDropTimer, suns, bullets, particles, mowerEntities;\nlet gameSeed, actionLog;\nlet curLevel = 0, curZombies = [\"normal\",\"conehead\"];\nlet gameMode = \"normal\", collectedSun = 0;\nlet lbTab = \"clears\";\nlet paused = false;\nlet curCardOrder = CARD_ORDER;\nconst MOWER_SPEED = 480;\nconst overlay = document.getElementById(\"overlay\");\nconst ovTitle = document.getElementById(\"ovTitle\");\nconst ovText = document.getElementById(\"ovText\");\nconst ovBtn = document.getElementById(\"ovBtn\");\nconst ovLB = document.getElementById(\"ovLeaderboard\");\nconst cheatInput = document.getElementById(\"cheatInput\");\nlet sunClickCount = 0;\n\n/* 填充排行榜 HTML */\nfunction fillLeaderboardHTML(){\n  const lb = window.__LEADERBOARD__ || [];\n  if(!lb.length){ ovLB.innerHTML = \"\"; ovLB.style.display = \"none\"; return; }\n  ovLB.style.display = \"block\";\n  let rows = lb.map((e,i)=>{\n    const m = i===0?\"🥇\":i===1?\"🥈\":i===2?\"🥉\":(i+1)+\".\";\n    return '<div class=\"lb-row\"><span>'+m+\" \"+e.name+\"</span><span>\"+e.count+\" 次</span></div>\";\n  }).join(\"\");\n  ovLB.innerHTML = \"<h3>🏆 通关排行榜</h3>\" + rows + '<div class=\"lb-note\">只有通关第五关才会记入排行榜</div>';\n}\n\nfunction newGame(seed, levelId, mode){\n  const lv = LEVELS[levelId !== undefined ? levelId : 0];\n  curLevel = lv.id;\n  gameMode = mode || \"normal\";\n  curZombies = lv.zombies.slice();\n  if(gameMode === \"weekly\" && window.__WEEK__ && window.__WEEK__.zombies){\n    curZombies = window.__WEEK__.zombies.slice();\n  }\n  curCardOrder = lv.plants ? lv.plants.slice() : CARD_ORDER;\n  ROWS = lv.rows;\n  GRID_Y = calcGridY(ROWS);\n  INIT_SUN = lv.initSun;\n  NUM_FLAGS = lv.flags;\n\n  gameSeed = (seed === undefined) ? (Date.now() & 0xffffffff) : seed;\n  rng = makeRng(gameSeed);\n  state = \"play\";\n  lastTime = 0;\n  mouse = {x:0, y:0, click:false};\n  selected = null;\n  shovelActive = false;\n  grid = [];\n  for(let y=0;y<ROWS;y++){ grid.push(new Array(COLS).fill(null)); }\n  zombies = []; bullets = []; suns = []; particles = [];\n  sun = INIT_SUN;\n  collectedSun = 0;\n  paused = false;\n  sunDropTimer = 4000;\n  cardCd = {}; CARD_ORDER.forEach(k=>cardCd[k]=0);\n  mowers = new Array(ROWS).fill(true);\n  mowerEntities = [];\n  waveIndex = 0;\n  zombiesToSpawn = [];\n  spawnTimer = 0;\n  waveTimer = 6000;\n  bigWaveWarning = 0;\n  actionLog = [];\n  overlay.classList.remove(\"show\");\n}\nlet grid, zombies, sun, cardCd, bigWaveWarning;\n\n/* ===== 波次生成（参考 pypvz level.py createWaves） ===== */\nfunction buildWave(n){\n  let vol = Math.floor(n*0.8/2)+1;\n  let big = (n % 10 === 0);\n  if(big) vol = Math.floor(vol*2.5);\n  let list = [];\n  if(big) list.push(\"flag\");\n  for(let i=list.length;i<vol;i++){\n    const r = rng();\n    if(curZombies.includes(\"buckethead\") && n >= 5 && r < 0.15){\n      list.push(\"buckethead\");\n    } else if(curZombies.includes(\"polevaulter\") && n >= 3 && r < 0.25){\n      list.push(\"polevaulter\");\n    } else if(curZombies.includes(\"conehead\") && n >= 3 && r < Math.min(0.15 + n*0.03, 0.45)){\n      list.push(\"conehead\");\n    } else if(curZombies.includes(\"football\") && n >= 5 && rng() < 0.18){\n      list.push(\"football\");\n    } else if(curZombies.includes(\"screendoor\") && n >= 4 && rng() < 0.18){\n      list.push(\"screendoor\");\n    } else if(curZombies.includes(\"newspaper\") && n >= 3 && rng() < 0.20){\n      list.push(\"newspaper\");\n    } else {\n      list.push(\"normal\");\n    }\n  }\n  return list;\n}\n\n/* ===== 坐标转换 ===== */\nfunction cellAt(px, py){\n  const cx = Math.floor((px-GRID_X)/CELL_W);\n  const cy = Math.floor((py-GRID_Y)/CELL_H);\n  if(cx<0||cx>=COLS||cy<0||cy>=ROWS) return null;\n  return {x:cx, y:cy};\n}\nfunction cellCenter(cx, cy){\n  return { x: GRID_X + cx*CELL_W + CELL_W/2, y: GRID_Y + cy*CELL_H + CELL_H/2 };\n}\n\n/* ===== 绘制：草地背景 ===== */\nfunction drawBackground(){\n  for(let y=0;y<ROWS;y++){\n    ctx.fillStyle = (y%2===0) ? \"#a8d96e\" : \"#b4e07a\";\n    ctx.fillRect(GRID_X, GRID_Y+y*CELL_H, COLS*CELL_W, CELL_H);\n  }\n  ctx.strokeStyle = \"rgba(90,140,50,.18)\";\n  ctx.lineWidth = 1;\n  for(let x=0;x<=COLS;x++){\n    ctx.beginPath();\n    ctx.moveTo(GRID_X+x*CELL_W, GRID_Y);\n    ctx.lineTo(GRID_X+x*CELL_W, GRID_Y+ROWS*CELL_H);\n    ctx.stroke();\n  }\n  for(let y=0;y<=ROWS;y++){\n    ctx.beginPath();\n    ctx.moveTo(GRID_X, GRID_Y+y*CELL_H);\n    ctx.lineTo(GRID_X+COLS*CELL_W, GRID_Y+y*CELL_H);\n    ctx.stroke();\n  }\n  const houseGrad = ctx.createLinearGradient(0,0,GRID_X,0);\n  houseGrad.addColorStop(0,\"#d9b88a\"); houseGrad.addColorStop(1,\"#e8d4a8\");\n  ctx.fillStyle = houseGrad;\n  ctx.fillRect(0, GRID_Y, GRID_X, ROWS*CELL_H);\n  ctx.fillStyle = \"#c4915a\";\n  ctx.fillRect(20, GRID_Y+40, 80, ROWS*CELL_H-60);\n  ctx.fillStyle = \"#a86a3a\";\n  ctx.beginPath();\n  ctx.moveTo(10, GRID_Y+40); ctx.lineTo(60, GRID_Y+0); ctx.lineTo(110, GRID_Y+40);\n  ctx.closePath(); ctx.fill();\n  ctx.fillStyle = \"#7a4a28\";\n  ctx.fillRect(45, GRID_Y+ROWS*CELL_H-50, 30, 40);\n  for(let y=0;y<ROWS;y++){\n    if(!mowers[y]) continue;\n    const my = GRID_Y + y*CELL_H + CELL_H/2;\n    drawMowerBody(GRID_X-26, my);\n  }\n  const barGrad = ctx.createLinearGradient(0,0,0,GRID_Y-20);\n  barGrad.addColorStop(0,\"#8b5a2b\"); barGrad.addColorStop(1,\"#a86d35\");\n  ctx.fillStyle = barGrad;\n  ctx.fillRect(0, 0, W, GRID_Y-20);\n}\n\n/* 割草机车身 */\nfunction drawMowerBody(x, cy){\n  ctx.fillStyle = \"rgba(0,0,0,.15)\";\n  ctx.beginPath(); ctx.ellipse(x+11, cy+16, 14, 4, 0, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#9aa0a6\";\n  ctx.fillRect(x, cy-12, 22, 22);\n  ctx.fillStyle = \"#7a8086\";\n  ctx.fillRect(x+3, cy-15, 16, 6);\n  ctx.strokeStyle = \"#5f6368\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(x+19, cy-12); ctx.lineTo(x+26, cy-16); ctx.stroke();\n  ctx.fillStyle = \"#c0c4c8\";\n  ctx.fillRect(x-4, cy-4, 6, 14);\n  ctx.strokeStyle = \"#5f6368\"; ctx.lineWidth = 1;\n  for(let i=0;i<3;i++){\n    ctx.beginPath(); ctx.moveTo(x-4, cy-4+i*5); ctx.lineTo(x+2, cy-4+i*5); ctx.stroke();\n  }\n  ctx.fillStyle = \"#3a3d42\";\n  ctx.beginPath(); ctx.arc(x+6, cy+10, 5, 0, 7); ctx.fill();\n  ctx.beginPath(); ctx.arc(x+16, cy+10, 5, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#8a8e92\";\n  ctx.beginPath(); ctx.arc(x+6, cy+10, 2, 0, 7); ctx.fill();\n  ctx.beginPath(); ctx.arc(x+16, cy+10, 2, 0, 7); ctx.fill();\n}\n\n/* ===== 绘制：植物 ===== */\nfunction drawPlant(p, cx, cy){\n  const t = p.type;\n  ctx.save();\n  ctx.translate(cx, cy);\n  const bob = Math.sin(p.anim*0.004 + p.cx*0.7)*2;\n  ctx.translate(0, bob);\n  if(t===\"sunflower\") drawSunflower(p);\n  else if(t===\"peashooter\") drawPeashooter(p);\n  else if(t===\"repeaterpea\") drawRepeater(p);\n  else if(t===\"snowpea\") drawSnowPea(p);\n  else if(t===\"chomper\") drawChomper(p);\n  else if(t===\"threepeater\") drawThreepeater(p);\n  else if(t===\"wallnut\") drawWallnut(p);\n  else if(t===\"potatomine\") drawPotato(p);\n  else if(t===\"cherrybomb\") drawCherry(p);\n  ctx.restore();\n  const def = PLANTS[t];\n  if(p.hp < def.hp){\n    const w = 44, hpf = p.hp/def.hp;\n    ctx.fillStyle = \"rgba(0,0,0,.35)\";\n    ctx.fillRect(cx-w/2, cy-32, w, 4);\n    ctx.fillStyle = hpf>0.5?\"#7ec850\":(hpf>0.25?\"#f0a830\":\"#e0584c\");\n    ctx.fillRect(cx-w/2, cy-32, w*hpf, 4);\n  }\n}\nfunction drawSunflower(p){\n  const glow = p.sunTimer != null && p.sunTimer < 1500;\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(0,20); ctx.lineTo(0,36); ctx.stroke();\n  if(p.bounceT > 0){ ctx.translate(0, -Math.sin((1-p.bounceT/300)*Math.PI)*8); }\n  const r = 18;\n  if(glow){\n    const pulse = 0.6 + Math.sin(p.anim*0.02)*0.4;\n    const gg = ctx.createRadialGradient(0,-6,4,0,-6,30);\n    gg.addColorStop(0, \"rgba(255,240,150,\"+(0.55*pulse)+\")\");\n    gg.addColorStop(1, \"rgba(255,240,150,0)\");\n    ctx.fillStyle = gg;\n    ctx.beginPath(); ctx.arc(0,-6,30,0,7); ctx.fill();\n  }\n  ctx.fillStyle = glow ? \"#ffe066\" : \"#ffc928\";\n  for(let i=0;i<8;i++){\n    const a = i*Math.PI/4 + p.anim*0.0008;\n    ctx.beginPath();\n    ctx.ellipse(Math.cos(a)*r, Math.sin(a)*r - 6, 7, 11, a, 0, 7);\n    ctx.fill();\n  }\n  ctx.fillStyle = glow ? \"#d9a030\" : \"#8b5a2b\";\n  ctx.beginPath(); ctx.arc(0,-6,12,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-4,-8,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-8,2,0,7); ctx.fill();\n  ctx.strokeStyle = \"#3a2a1a\"; ctx.lineWidth = 1.5;\n  ctx.beginPath(); ctx.arc(0,-4,3,0.1,Math.PI-0.1); ctx.stroke();\n}\nfunction drawPeashooter(p){\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(-2,16); ctx.lineTo(-2,34); ctx.stroke();\n  ctx.fillStyle = \"#6cbb3c\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#6cbb3c\";\n  ctx.beginPath(); ctx.arc(0,-2,15,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a9a2c\";\n  ctx.beginPath(); ctx.ellipse(14,-4,7,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#2a6a1c\";\n  ctx.beginPath(); ctx.arc(18,-4,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-2,-6,4,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-1,-6,2,0,7); ctx.fill();\n}\nfunction drawRepeater(p){\n  ctx.strokeStyle = \"#3a7a1a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(-2,16); ctx.lineTo(-2,34); ctx.stroke();\n  ctx.fillStyle = \"#5aa530\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a9a2c\";\n  ctx.beginPath(); ctx.arc(-6,-4,13,0,7); ctx.fill();\n  ctx.fillStyle = \"#5aa530\";\n  ctx.beginPath(); ctx.arc(0,-2,15,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a8a1c\";\n  ctx.beginPath(); ctx.ellipse(14,-4,8,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#2a5a0c\";\n  ctx.beginPath(); ctx.arc(18,-4,3.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-2,-6,4,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-1,-6,2,0,7); ctx.fill();\n}\nfunction drawSnowPea(p){\n  ctx.strokeStyle = \"#3a8a8a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(-2,16); ctx.lineTo(-2,34); ctx.stroke();\n  ctx.fillStyle = \"#5ab8e0\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#5ab8e0\";\n  ctx.beginPath(); ctx.arc(0,-2,15,0,7); ctx.fill();\n  ctx.fillStyle = \"#4a9ac0\";\n  ctx.beginPath(); ctx.ellipse(14,-4,7,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#2a6a8a\";\n  ctx.beginPath(); ctx.arc(18,-4,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-2,-6,4,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-1,-6,2,0,7); ctx.fill();\n  ctx.fillStyle = \"rgba(180,230,255,.4)\";\n  ctx.beginPath(); ctx.arc(-4,-8,3,0,7); ctx.fill();\n}\nfunction drawChomper(p){\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(0,16); ctx.lineTo(0,34); ctx.stroke();\n  ctx.fillStyle = \"#6cbb3c\";\n  ctx.beginPath(); ctx.ellipse(-12,24,7,4,-0.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.ellipse(12,24,7,4,0.5,0,7); ctx.fill();\n  const openRaw = p.chewing ? (Math.sin(p.anim*0.012)*0.08+0.05) : (Math.sin(p.anim*0.003)*0.15+0.45);\n  const open = Math.max(0.01, openRaw);\n  const belly = p.chewing ? (Math.sin(p.anim*0.008)*2+3) : 0;\n  ctx.fillStyle = \"#b85a8a\";\n  ctx.beginPath(); ctx.ellipse(0,2+belly*0.3,18+belly*0.5,12+belly*0.8,0,0,Math.PI); ctx.fill();\n  ctx.fillStyle = \"#d870b8\";\n  ctx.beginPath(); ctx.ellipse(0,-6,18,14,0,Math.PI,Math.PI*2); ctx.fill();\n  ctx.fillStyle = \"#8a2a4a\";\n  ctx.beginPath(); ctx.ellipse(0,-2,14,8*open,0,0,Math.PI*open); ctx.fill();\n  if(!p.chewing){\n    ctx.fillStyle = \"#fff\";\n    for(let i=0;i<5;i++){\n      const tx = -10+i*5;\n      ctx.beginPath();\n      ctx.moveTo(tx, -4); ctx.lineTo(tx+3, -4); ctx.lineTo(tx+1.5, -4+5*open);\n      ctx.fill();\n    }\n    for(let i=0;i<4;i++){\n      const tx = -8+i*5;\n      ctx.beginPath();\n      ctx.moveTo(tx, 0); ctx.lineTo(tx+3, 0); ctx.lineTo(tx+1.5, 0-4*open);\n      ctx.fill();\n    }\n  }\n  if(p.chewing){\n    ctx.fillStyle = \"rgba(100,180,255,.8)\";\n    const sweat = Math.sin(p.anim*0.006)*1.5;\n    ctx.beginPath(); ctx.ellipse(-13,-17+sweat,2.5,4,0,0,7); ctx.fill();\n    ctx.beginPath(); ctx.ellipse(13,-17+sweat,2.5,4,0,0,7); ctx.fill();\n  }\n  if(p.chewing){\n    ctx.strokeStyle = \"#3a2a1a\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.arc(-8,-14,4,0.2,Math.PI-0.2); ctx.stroke();\n    ctx.beginPath(); ctx.arc(8,-14,4,0.2,Math.PI-0.2); ctx.stroke();\n  } else {\n    ctx.fillStyle = \"#fff\";\n    ctx.beginPath(); ctx.arc(-8,-14,4,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(8,-14,4,0,7); ctx.fill();\n    ctx.fillStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(-7,-13,2,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(9,-13,2,0,7); ctx.fill();\n    ctx.fillStyle = \"rgba(255,255,255,.8)\";\n    ctx.beginPath(); ctx.arc(-6,-14,0.8,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(10,-14,0.8,0,7); ctx.fill();\n  }\n  ctx.strokeStyle = \"#d870b8\"; ctx.lineWidth = 2;\n  ctx.beginPath();\n  ctx.moveTo(0,-18); ctx.quadraticCurveTo(-4,-24,-8,-22);\n  ctx.stroke();\n  ctx.beginPath();\n  ctx.moveTo(0,-18); ctx.quadraticCurveTo(4,-24,8,-22);\n  ctx.stroke();\n  ctx.fillStyle = \"#e890c8\";\n  ctx.beginPath(); ctx.arc(-8,-22,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(8,-22,2,0,7); ctx.fill();\n}\nfunction drawThreepeater(p){\n  /* 茎 + 对称底叶 */\n  ctx.strokeStyle = \"#5a8a2a\"; ctx.lineWidth = 5;\n  ctx.beginPath(); ctx.moveTo(0,18); ctx.lineTo(0,34); ctx.stroke();\n  ctx.fillStyle = \"#5aa530\";\n  ctx.beginPath(); ctx.ellipse(-11,28,7,4,-0.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.ellipse(11,28,7,4,0.5,0,7); ctx.fill();\n  /* 三个头垂直堆叠，各带豌豆射手炮口与眼睛 */\n  const heads = [{y:-14,r:8.5},{y:-2,r:9.5},{y:10,r:8.5}];\n  for(const h of heads){\n    const hx = -3;\n    ctx.fillStyle = \"#6cbb3c\";\n    ctx.beginPath(); ctx.arc(hx, h.y, h.r, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#5aa530\";\n    ctx.beginPath(); ctx.arc(hx, h.y+h.r*0.45, h.r*0.85, 0.2, Math.PI-0.2); ctx.fill();\n    ctx.fillStyle = \"#4a9a2c\";\n    ctx.beginPath(); ctx.ellipse(hx+h.r-1, h.y, 5, h.r*0.55, 0, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#2a6a1c\";\n    ctx.beginPath(); ctx.arc(hx+h.r+2, h.y, 2.2, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#fff\";\n    ctx.beginPath(); ctx.arc(hx-2, h.y-2.5, 2.3, 0, 7); ctx.fill();\n    ctx.fillStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(hx-1.2, h.y-2.5, 1.1, 0, 7); ctx.fill();\n  }\n  /* 头间小叶片点缀 */\n  ctx.fillStyle = \"#7acb4c\";\n  ctx.beginPath(); ctx.ellipse(-3,-8,3.5,2,0,0,7); ctx.fill();\n  ctx.beginPath(); ctx.ellipse(-3,4,3.5,2,0,0,7); ctx.fill();\n}\nfunction drawWallnut(p){\n  const f = p.hp/WALLNUT_HEALTH;\n  ctx.fillStyle = \"#c98a3a\";\n  ctx.beginPath(); ctx.ellipse(0,4,18,22,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#b87a2a\";\n  ctx.beginPath(); ctx.ellipse(0,14,14,10,0,0,7); ctx.fill();\n  ctx.fillStyle = \"rgba(255,220,160,.25)\";\n  ctx.beginPath(); ctx.ellipse(-6,-6,6,8,-0.3,0,7); ctx.fill();\n  if(f<=0.66){\n    ctx.strokeStyle = \"#7a4a1a\"; ctx.lineWidth = 1.8;\n    ctx.beginPath(); ctx.moveTo(-9,-8); ctx.lineTo(-5,0); ctx.lineTo(-8,8); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(-3,-10); ctx.lineTo(-1,-2); ctx.stroke();\n  }\n  if(f<=0.33){\n    ctx.fillStyle = \"#5a3a1a\";\n    ctx.beginPath(); ctx.ellipse(10,-2,8,10,0.3,0,7); ctx.fill();\n    ctx.strokeStyle = \"#5a3010\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.moveTo(6,-10); ctx.lineTo(2,2); ctx.lineTo(8,10); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(-10,2); ctx.lineTo(-4,6); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(0,-12); ctx.lineTo(-3,-4); ctx.stroke();\n  }\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-5,-2,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(5,-2,2,0,7); ctx.fill();\n  ctx.strokeStyle = \"#3a2a1a\"; ctx.lineWidth = 1.5;\n  if(f>0.66){\n    ctx.beginPath(); ctx.arc(0,4,4,0.1,Math.PI-0.1); ctx.stroke();\n  } else if(f>0.33){\n    ctx.beginPath(); ctx.moveTo(-3,6); ctx.lineTo(3,6); ctx.stroke();\n  } else {\n    ctx.beginPath(); ctx.ellipse(0,7,3,2,0,0,7); ctx.fill();\n    ctx.strokeStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(-5,-4,3,Math.PI+0.3,Math.PI*2-0.3); ctx.stroke();\n    ctx.beginPath(); ctx.arc(5,-4,3,Math.PI+0.3,Math.PI*2-0.3); ctx.stroke();\n  }\n}\nfunction drawPotato(p){\n  if(!p.armed){\n    ctx.fillStyle = \"#8b6a3a\";\n    ctx.beginPath(); ctx.ellipse(0,16,16,8,0,0,Math.PI); ctx.fill();\n    ctx.fillStyle = \"#b8862b\";\n    ctx.beginPath(); ctx.ellipse(0,16,16,8,0,Math.PI,0); ctx.fill();\n    ctx.strokeStyle = \"#5a3a1a\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.moveTo(0,12); ctx.quadraticCurveTo(4,2,10,0); ctx.stroke();\n    return;\n  }\n  ctx.fillStyle = \"#b8862b\";\n  ctx.beginPath(); ctx.ellipse(0,8,16,14,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#a8761b\";\n  ctx.beginPath(); ctx.ellipse(0,14,12,8,0,0,7); ctx.fill();\n  ctx.strokeStyle = \"#5a3a1a\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(0,-6); ctx.lineTo(6,-14); ctx.stroke();\n  const sp = 3 + Math.sin(p.anim*0.02)*2;\n  ctx.fillStyle = \"#ff8c42\";\n  ctx.beginPath(); ctx.arc(6,-14,sp,0,7); ctx.fill();\n  ctx.fillStyle = \"#ffe066\";\n  ctx.beginPath(); ctx.arc(6,-14,sp*0.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a2a1a\";\n  ctx.beginPath(); ctx.arc(-4,4,2,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,4,2,0,7); ctx.fill();\n}\nfunction drawCherry(p){\n  const blink = Math.sin(p.anim*0.01)>0;\n  ctx.fillStyle = \"#e04444\";\n  ctx.beginPath(); ctx.arc(-8,2,13,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(8,2,13,0,7); ctx.fill();\n  ctx.fillStyle = \"#c03434\";\n  ctx.beginPath(); ctx.arc(-8,8,9,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(8,8,9,0,7); ctx.fill();\n  ctx.strokeStyle = \"#5a3a1a\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.moveTo(0,-10); ctx.quadraticCurveTo(6,-18,12,-20); ctx.stroke();\n  if(blink){\n    ctx.fillStyle = \"#3a2a1a\";\n    ctx.beginPath(); ctx.arc(-10,-2,1.5,0,7); ctx.fill();\n    ctx.beginPath(); ctx.arc(6,-2,1.5,0,7); ctx.fill();\n  }\n}\n\n/* ===== 绘制：僵尸 ===== */\nfunction drawZombie(z){\n  const cx = z.x, cy = z.y;\n  ctx.save();\n  ctx.translate(cx, cy);\n  /* 撑杆跳跳跃动画 */\n  if(z.jumping){\n    const jp = z.jumpProgress || 0;\n    ctx.translate(0, -Math.sin(jp*Math.PI)*30);\n  }\n  const walk = Math.sin(z.anim*0.008)*3;\n  ctx.fillStyle = \"rgba(0,0,0,.18)\";\n  ctx.beginPath(); ctx.ellipse(0,30,16,5,0,0,7); ctx.fill();\n  ctx.fillStyle = \"#7a8b5a\";\n  ctx.fillRect(-8, 14+walk, 6, 14);\n  ctx.fillRect(2, 14-walk, 6, 14);\n  ctx.fillStyle = \"#8a9b6a\";\n  ctx.beginPath(); ctx.roundRect(-11, -6, 22, 22, 5); ctx.fill();\n  ctx.fillStyle = \"#9aab7a\";\n  ctx.fillRect(-16, 0, 8, 6);\n  ctx.fillRect(8, 0, 8, 6);\n  ctx.fillStyle = \"#b5c098\";\n  ctx.beginPath(); ctx.arc(0, -16, 12, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#5a4a3a\";\n  ctx.beginPath(); ctx.arc(0,-22,12,Math.PI*1.1,Math.PI*1.9); ctx.fill();\n  ctx.fillStyle = \"#fff\";\n  ctx.beginPath(); ctx.arc(-4,-17,3,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-17,3,0,7); ctx.fill();\n  ctx.fillStyle = \"#c0342a\";\n  ctx.beginPath(); ctx.arc(-4,-17,1.5,0,7); ctx.fill();\n  ctx.beginPath(); ctx.arc(4,-17,1.5,0,7); ctx.fill();\n  ctx.fillStyle = \"#3a1a1a\";\n  ctx.fillRect(-4,-10,8,3);\n  ctx.fillStyle = \"#eee\";\n  ctx.fillRect(-3,-10,2,2); ctx.fillRect(1,-10,2,2);\n  /* 路障 */\n  if(z.kind === \"conehead\" && z.helmet > 0){\n    const hf = z.helmet / z.maxHelmet;\n    ctx.fillStyle = \"#e8822a\";\n    ctx.beginPath();\n    ctx.moveTo(-10, -24); ctx.lineTo(10, -24); ctx.lineTo(0, -43);\n    ctx.closePath(); ctx.fill();\n    ctx.fillStyle = \"#c46818\";\n    ctx.fillRect(-10, -25, 20, 3);\n    ctx.fillStyle = \"rgba(255,255,255,.55)\";\n    ctx.fillRect(-7, -31, 14, 3);\n    ctx.fillRect(-5, -37, 10, 2.5);\n    if(hf < 0.6){\n      ctx.strokeStyle = \"rgba(80,40,10,.7)\"; ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.moveTo(-4,-26); ctx.lineTo(2,-33); ctx.lineTo(-2,-39); ctx.stroke();\n    }\n    if(hf < 0.3){\n      ctx.beginPath(); ctx.moveTo(5,-28); ctx.lineTo(-1,-35); ctx.stroke();\n    }\n  }\n  /* 铁桶 */\n  if(z.kind === \"buckethead\" && z.helmet > 0){\n    const hf = z.helmet / z.maxHelmet;\n    ctx.fillStyle = \"#888\";\n    ctx.fillRect(-12, -30, 24, 20);\n    ctx.fillStyle = \"#aaa\";\n    ctx.fillRect(-12, -30, 24, 4);\n    ctx.fillStyle = \"#666\";\n    ctx.fillRect(-12, -14, 24, 4);\n    ctx.fillStyle = \"rgba(255,255,255,.2)\";\n    ctx.fillRect(-9, -28, 4, 16);\n    if(hf < 0.6){\n      ctx.strokeStyle = \"rgba(40,40,40,.6)\"; ctx.lineWidth = 1.5;\n      ctx.beginPath(); ctx.moveTo(-6,-26); ctx.lineTo(2,-18); ctx.stroke();\n    }\n    if(hf < 0.3){\n      ctx.beginPath(); ctx.moveTo(6,-28); ctx.lineTo(-2,-16); ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(-8,-20); ctx.lineTo(0,-14); ctx.stroke();\n    }\n  }\n  /* 撑杆跳杆子 */\n  if(z.kind === \"polevaulter\" && z.hasPole){\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 3;\n    ctx.beginPath();\n    ctx.moveTo(-18, 10); ctx.quadraticCurveTo(-30, -20, -10, -35);\n    ctx.stroke();\n  }\n  /* 旗帜 */\n  if(z.kind===\"flag\"){\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.moveTo(12,-28); ctx.lineTo(12,-6); ctx.stroke();\n    ctx.fillStyle = \"#e04444\";\n    const fw = 14 + Math.sin(z.anim*0.01)*3;\n    ctx.beginPath();\n    ctx.moveTo(12,-28); ctx.lineTo(12+fw,-24); ctx.lineTo(12,-18);\n    ctx.closePath(); ctx.fill();\n  }\n  /* 读报僵尸：报纸盾 / 狂暴表情 */\n  if(z.kind === \"newspaper\"){\n    if(z.helmet > 0){\n      ctx.fillStyle = \"#f5f0e0\";\n      ctx.fillRect(-15, -8, 20, 24);\n      ctx.strokeStyle = \"#c0b890\"; ctx.lineWidth = 1;\n      ctx.strokeRect(-15, -8, 20, 24);\n      ctx.fillStyle = \"#5a4a3a\";\n      ctx.fillRect(-13, -5, 16, 1.5);\n      for(let i=0;i<5;i++){ ctx.fillRect(-13, -1+i*4, 16, 0.8); }\n    } else {\n      ctx.fillStyle = \"#c0342a\";\n      ctx.beginPath(); ctx.arc(-4,-17,2.2,0,7); ctx.fill();\n      ctx.beginPath(); ctx.arc(4,-17,2.2,0,7); ctx.fill();\n      ctx.strokeStyle = \"#c0342a\"; ctx.lineWidth = 1.6;\n      ctx.beginPath(); ctx.moveTo(-7,-21); ctx.lineTo(-2,-19); ctx.stroke();\n      ctx.beginPath(); ctx.moveTo(7,-21); ctx.lineTo(2,-19); ctx.stroke();\n      if(Math.floor(z.anim/150)%2 === 0){\n        ctx.fillStyle = \"#e04444\";\n        ctx.font = \"bold 14px sans-serif\"; ctx.textAlign = \"center\";\n        ctx.fillText(\"!\", 13, -22);\n      }\n    }\n  }\n  /* 橄榄球僵尸：头盔 + 护甲 */\n  if(z.kind === \"football\"){\n    ctx.fillStyle = \"#3a5a3a\";\n    ctx.beginPath(); ctx.roundRect(-14, -8, 28, 22, 5); ctx.fill();\n    if(z.helmet > 0){\n      const hf = z.helmet / z.maxHelmet;\n      ctx.fillStyle = \"#4a3a2a\";\n      ctx.beginPath(); ctx.ellipse(0, -22, 14, 11, 0, Math.PI, 0); ctx.fill();\n      ctx.fillStyle = \"#d8b020\";\n      ctx.fillRect(-13, -20, 26, 3);\n      ctx.strokeStyle = \"#1a1a1a\"; ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.moveTo(-9,-22); ctx.lineTo(9,-22); ctx.stroke();\n      for(let i=-2;i<=2;i++){ ctx.beginPath(); ctx.moveTo(i*4,-26); ctx.lineTo(i*4,-18); ctx.stroke(); }\n      ctx.fillStyle = \"rgba(0,0,0,.25)\";\n      ctx.fillRect(-12, -28, 4, 8);\n      if(hf < 0.5){\n        ctx.strokeStyle = \"rgba(20,20,20,.6)\"; ctx.lineWidth = 1.5;\n        ctx.beginPath(); ctx.moveTo(-6,-24); ctx.lineTo(4,-18); ctx.stroke();\n      }\n    }\n  }\n  /* 铁网门僵尸：铁网门盾（挡在前方左侧，迎向豌豆） */\n  if(z.kind === \"screendoor\" && z.helmet > 0){\n    const hf = z.helmet / z.maxHelmet;\n    ctx.fillStyle = \"#9a9a9a\";\n    ctx.fillRect(-18, -26, 12, 48);\n    ctx.fillStyle = \"#7a7a7a\";\n    ctx.fillRect(-18, -26, 12, 4);\n    ctx.fillRect(-18, 18, 12, 4);\n    ctx.strokeStyle = \"#4a4a4a\"; ctx.lineWidth = 0.7;\n    for(let i=1;i<6;i++){ ctx.beginPath(); ctx.moveTo(-18, -26+i*8); ctx.lineTo(-6, -26+i*8); ctx.stroke(); }\n    for(let i=1;i<2;i++){ ctx.beginPath(); ctx.moveTo(-18+i*6, -26); ctx.lineTo(-18+i*6, 22); ctx.stroke(); }\n    ctx.beginPath(); ctx.moveTo(-12, -26); ctx.lineTo(-12, 22); ctx.stroke();\n    if(hf < 0.5){\n      ctx.strokeStyle = \"rgba(40,40,40,.6)\"; ctx.lineWidth = 1.2;\n      ctx.beginPath(); ctx.moveTo(-16,-18); ctx.lineTo(-8,2); ctx.stroke();\n    }\n  }\n  /* 减速冰冻效果 */\n  if(z.slowed > 0){\n    ctx.fillStyle = \"rgba(90,184,224,.35)\";\n    ctx.beginPath(); ctx.roundRect(-17, -28, 34, 54, 8); ctx.fill();\n    ctx.fillStyle = \"rgba(180,230,255,.7)\";\n    ctx.beginPath(); ctx.arc(-12, -10, 2, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(10, -5, 1.5, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(8, 15, 2, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(-10, 20, 1.5, 0, 7); ctx.fill();\n    ctx.beginPath(); ctx.arc(0, -22, 1.8, 0, 7); ctx.fill();\n  }\n  ctx.restore();\n  /* 防具血条 */\n  if(z.maxHelmet > 0 && z.helmet > 0){\n    const w = 28, hf = z.helmet/z.maxHelmet;\n    ctx.fillStyle = \"rgba(0,0,0,.4)\";\n    ctx.fillRect(cx-w/2, cy-52, w, 3.5);\n    ctx.fillStyle = (z.kind===\"buckethead\"||z.kind===\"football\"||z.kind===\"screendoor\") ? \"#aaa\" : (z.kind===\"newspaper\" ? \"#d8c8a0\" : \"#e8822a\");\n    ctx.fillRect(cx-w/2, cy-52, w*hf, 3.5);\n  }\n  /* 本体血条 */\n  const maxHp = ZOMBIE_TYPES[z.kind] ? ZOMBIE_TYPES[z.kind].hp : ZOMBIE_HEALTH;\n  if(z.hp < maxHp && !(z.maxHelmet > 0 && z.helmet > 0)){\n    const w = 30, hpf = z.hp/maxHp;\n    ctx.fillStyle = \"rgba(0,0,0,.35)\";\n    ctx.fillRect(cx-w/2, cy-38, w, 4);\n    ctx.fillStyle = hpf>0.5?\"#7ec850\":(hpf>0.25?\"#f0a830\":\"#e0584c\");\n    ctx.fillRect(cx-w/2, cy-38, w*hpf, 4);\n  }\n}\n\n/* ===== 绘制：阳光 ===== */\nfunction drawSun(s){\n  const r = 20;\n  const pulse = 1 + Math.sin(s.anim*0.006)*0.08;\n  const g = ctx.createRadialGradient(s.x,s.y,2,s.x,s.y,r*pulse*1.6);\n  g.addColorStop(0,\"rgba(255,230,120,.7)\");\n  g.addColorStop(1,\"rgba(255,230,120,0)\");\n  ctx.fillStyle = g;\n  ctx.beginPath(); ctx.arc(s.x,s.y,r*pulse*1.6,0,7); ctx.fill();\n  ctx.fillStyle = \"#ffd24a\";\n  ctx.beginPath(); ctx.arc(s.x,s.y,r*pulse,0,7); ctx.fill();\n  ctx.fillStyle = \"#ffe89a\";\n  ctx.beginPath(); ctx.arc(s.x-3,s.y-3,r*pulse*0.5,0,7); ctx.fill();\n  ctx.strokeStyle = \"rgba(255,210,74,.6)\"; ctx.lineWidth = 2;\n  for(let i=0;i<8;i++){\n    const a = i*Math.PI/4 + s.anim*0.002;\n    ctx.beginPath();\n    ctx.moveTo(s.x+Math.cos(a)*r*pulse, s.y+Math.sin(a)*r*pulse);\n    ctx.lineTo(s.x+Math.cos(a)*(r+5)*pulse, s.y+Math.sin(a)*(r+5)*pulse);\n    ctx.stroke();\n  }\n}\n\n/* ===== 绘制：子弹 ===== */\nfunction drawBullet(b){\n  if(b.ice){\n    ctx.fillStyle = \"rgba(90,184,224,.4)\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,7,0,7); ctx.fill();\n    ctx.fillStyle = \"#5ab8e0\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,5,0,7); ctx.fill();\n    ctx.fillStyle = \"#b0e8ff\";\n    ctx.beginPath(); ctx.arc(b.x-1,b.y-1,2,0,7); ctx.fill();\n  } else {\n    ctx.fillStyle = \"rgba(108,187,60,.4)\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,7,0,7); ctx.fill();\n    ctx.fillStyle = \"#7ec850\";\n    ctx.beginPath(); ctx.arc(b.x,b.y,5,0,7); ctx.fill();\n    ctx.fillStyle = \"#a8e07a\";\n    ctx.beginPath(); ctx.arc(b.x-1,b.y-1,2,0,7); ctx.fill();\n  }\n}\n\n/* ===== 绘制：粒子 ===== */\nfunction drawParticle(p){\n  ctx.globalAlpha = p.life/p.maxLife;\n  ctx.fillStyle = p.color;\n  ctx.beginPath(); ctx.arc(p.x,p.y,p.size,0,7); ctx.fill();\n  ctx.globalAlpha = 1;\n}\n\n/* ===== 绘制：UI ===== */\nfunction drawUI(now){\n  const cardX0 = 16, cardY = 10, cardW = 60, cardH = 78, gap = 6;\n  curCardOrder.forEach((key, i)=>{\n    const def = PLANTS[key];\n    const x = cardX0 + i*(cardW+gap);\n    const cdLeft = Math.max(0, cardCd[key] - now);\n    const affordable = sun >= def.cost;\n    const onCd = cdLeft > 0;\n    ctx.fillStyle = selected===key ? \"#fff3c4\" : \"#f4e4c8\";\n    ctx.strokeStyle = selected===key ? \"#e0a030\" : \"#c9a878\";\n    ctx.lineWidth = selected===key ? 3 : 1.5;\n    ctx.beginPath(); ctx.roundRect(x, cardY, cardW, cardH, 6); ctx.fill(); ctx.stroke();\n    ctx.save();\n    ctx.translate(x+cardW/2, cardY+26);\n    ctx.scale(0.62,0.62);\n    const fake = {anim:now, hp:def.hp, cx:i, armed:true};\n    if(key===\"sunflower\") drawSunflower(fake);\n    else if(key===\"peashooter\") drawPeashooter(fake);\n    else if(key===\"repeaterpea\") drawRepeater(fake);\n    else if(key===\"snowpea\") drawSnowPea(fake);\n    else if(key===\"chomper\") drawChomper(fake);\n    else if(key===\"threepeater\") drawThreepeater(fake);\n    else if(key===\"wallnut\") drawWallnut(fake);\n    else if(key===\"potatomine\") drawPotato(fake);\n    else if(key===\"cherrybomb\") drawCherry(fake);\n    ctx.restore();\n    ctx.fillStyle = affordable ? \"#5a4a3a\" : \"#c0342a\";\n    ctx.font = \"bold 12px sans-serif\";\n    ctx.textAlign = \"center\";\n    ctx.fillText(def.cost, x+cardW/2, cardY+cardH-6);\n    if(onCd){\n      const cdFrac = cdLeft / def.cd;\n      ctx.fillStyle = \"rgba(40,40,40,.55)\";\n      ctx.fillRect(x, cardY, cardW, cardH*cdFrac);\n    }\n    if(!affordable && !onCd){\n      ctx.fillStyle = \"rgba(80,80,80,.3)\";\n      ctx.fillRect(x, cardY, cardW, cardH);\n    }\n  });\n  const shX = cardX0 + curCardOrder.length*(cardW+gap) + 8;\n  ctx.save();\n  ctx.translate(shX+24, cardY+30);\n  if(shovelActive){ ctx.scale(1.12,1.12); }\n  ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 4;\n  ctx.beginPath(); ctx.moveTo(-6,-18); ctx.lineTo(6,14); ctx.stroke();\n  ctx.fillStyle = shovelActive ? \"#ffd24a\" : \"#c9a878\";\n  ctx.beginPath(); ctx.moveTo(-12,-22); ctx.lineTo(12,-22); ctx.lineTo(10,-10); ctx.lineTo(-10,-10); ctx.closePath(); ctx.fill();\n  ctx.restore();\n  const sx = W - 130, sy = cardY+24;\n  ctx.fillStyle = \"#fff3c4\";\n  ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.roundRect(sx, cardY, 114, 36, 8); ctx.fill(); ctx.stroke();\n  ctx.fillStyle = \"#ffd24a\";\n  ctx.beginPath(); ctx.arc(sx+20, cardY+18, 11, 0, 7); ctx.fill();\n  ctx.fillStyle = \"#8b5a2b\";\n  ctx.font = \"bold 18px sans-serif\"; ctx.textAlign = \"left\";\n  ctx.fillText(sun, sx+40, cardY+24);\n  const pbX = W-260, pbY = cardY+44, pbW = 240, pbH = 22;\n  ctx.fillStyle = \"#5a4030\";\n  ctx.beginPath(); ctx.roundRect(pbX, pbY, pbW, pbH, 6); ctx.fill();\n  const totalWaves = NUM_FLAGS*10;\n  const prog = Math.min(waveIndex/totalWaves, 1);\n  ctx.fillStyle = \"#7ec850\";\n  ctx.beginPath(); ctx.roundRect(pbX+2, pbY+2, (pbW-4)*prog, pbH-4, 4); ctx.fill();\n  for(let f=1; f<=NUM_FLAGS; f++){\n    const fx = pbX + (pbW * f*10/totalWaves);\n    ctx.fillStyle = f*10<=waveIndex ? \"#e04444\" : \"#fff\";\n    ctx.beginPath(); ctx.moveTo(fx, pbY-2); ctx.lineTo(fx+10, pbY+3); ctx.lineTo(fx, pbY+8); ctx.closePath(); ctx.fill();\n  }\n  ctx.fillStyle = \"#fff\"; ctx.font = \"11px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(\"进度\", pbX+pbW/2, pbY+16);\n  ctx.fillStyle = \"#ffd24a\"; ctx.font = \"bold 12px sans-serif\"; ctx.textAlign = \"left\";\n  ctx.fillText(LEVELS[curLevel].title, 16, cardY+cardH+14);\n  if(bigWaveWarning > 0){\n    ctx.fillStyle = \"rgba(200,40,40,\"+Math.min(bigWaveWarning/2000,0.5)+\")\";\n    ctx.fillRect(0,0,W,H);\n    if(bigWaveWarning > 1500){\n      ctx.fillStyle = \"#fff\";\n      ctx.font = \"bold 28px sans-serif\"; ctx.textAlign=\"center\";\n      ctx.fillText(\"一大波僵尸来袭\", W/2, H/2);\n    }\n  }\n  /* 暂停按钮（未暂停时显示在右上角） */\n  if(!paused){\n    const p = PAUSE_BTN;\n    const hover = mouse.x>=p.x&&mouse.x<=p.x+p.w&&mouse.y>=p.y&&mouse.y<=p.y+p.h;\n    ctx.fillStyle = hover ? \"#fff3c4\" : \"#f4e4c8\";\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 2;\n    ctx.beginPath(); ctx.roundRect(p.x, p.y, p.w, p.h, 8); ctx.fill(); ctx.stroke();\n    ctx.fillStyle = \"#8b5a2b\";\n    ctx.fillRect(p.x+12, p.y+10, 5, 16);\n    ctx.fillRect(p.x+23, p.y+10, 5, 16);\n  }\n}\n\n/* ===== 更新逻辑 ===== */\nfunction update(dt, now){\n  if(state !== \"play\" || paused) return;\n  sunDropTimer -= dt;\n  if(sunDropTimer <= 0){\n    sunDropTimer = SUN_DROP_INTERVAL * (0.7 + rng()*0.6);\n    const sx = GRID_X + 30 + rng()*(COLS*CELL_W-60);\n    suns.push({x:sx, y:-20, ty: GRID_Y + 40 + rng()*(ROWS*CELL_H-80), anim:now, life:SUN_LIVE_TIME, falling:true});\n  }\n  for(let i=suns.length-1;i>=0;i--){\n    const s = suns[i];\n    s.anim = now;\n    if(s.flying){\n      s.flyT += dt;\n      const t = Math.min(s.flyT/s.flyDur, 1);\n      const ease = 1 - Math.pow(1-t, 3);\n      s.x = s.fromX + (s.toX - s.fromX) * ease;\n      s.y = s.fromY + (s.toY - s.fromY) * ease - Math.sin(t*Math.PI)*50;\n      if(t >= 1){\n        sun += SUN_VALUE;\n        collectedSun += SUN_VALUE;\n        actionLog.push({t:performance.now(), e:\"sun\"});\n        spawnParticle(s.toX, s.toY, \"#ffd24a\", 6);\n        suns.splice(i,1);\n      }\n    } else if(s.bouncing){\n      s.vy += s.g * dt;\n      s.y += s.vy * dt;\n      if(s.y >= s.ty){\n        s.y = s.ty;\n        if(s.bounced < 1 && s.vy > 0.12){\n          s.vy = -s.vy * 0.4;\n          s.bounced++;\n        } else {\n          s.bouncing = false;\n          s.vy = 0;\n        }\n      }\n      s.life -= dt;\n      if(s.life <= 0) suns.splice(i,1);\n    } else {\n      if(s.falling){\n        if(s.y < s.ty) s.y += 40*dt/1000;\n        else { s.y = s.ty; s.falling = false; }\n      }\n      s.life -= dt;\n      if(s.life <= 0) suns.splice(i,1);\n    }\n  }\n  if(zombiesToSpawn.length === 0 && waveIndex < NUM_FLAGS*10){\n    waveTimer -= dt;\n    if(waveTimer <= 0){\n      waveIndex++;\n      zombiesToSpawn = buildWave(waveIndex);\n      if(waveIndex % 10 === 0) bigWaveWarning = 2500;\n      waveTimer = (waveIndex % 10 === 0) ? 22000 : (12000 + rng()*6000);\n      spawnTimer = 0;\n    }\n  } else if(zombiesToSpawn.length > 0){\n    spawnTimer -= dt;\n    if(spawnTimer <= 0){\n      const kind = zombiesToSpawn.shift();\n      const row = Math.floor(rng()*ROWS);\n      const cy = GRID_Y + row*CELL_H + CELL_H/2 + 6;\n      const zt = ZOMBIE_TYPES[kind] || ZOMBIE_TYPES.normal;\n      zombies.push({\n        x: SPAWN_X + rng()*30, y: cy, row:row, kind:kind,\n        hp: zt.hp, helmet: zt.helmet, maxHelmet: zt.helmet,\n        anim: now, walkT:0, attackT:0, attackTarget:null, dead:false,\n        hasPole: kind===\"polevaulter\", jumping:false, jumpProgress:0,\n        slowed: 0, enraged: false\n      });\n      spawnTimer = 600 + rng()*800;\n    }\n  }\n  if(bigWaveWarning > 0) bigWaveWarning -= dt;\n\n  /* 植物更新 */\n  for(let y=0;y<ROWS;y++){\n    for(let x=0;x<COLS;x++){\n      const p = grid[y][x];\n      if(!p) continue;\n      p.anim = now;\n      if(p.bounceT) p.bounceT = Math.max(0, p.bounceT - dt);\n      if(p.type === \"sunflower\"){\n        p.sunTimer -= dt;\n        if(p.sunTimer <= 0){\n          p.sunTimer = SUNFLOWER_INTERVAL;\n          p.bounceT = 300;\n          const ox = (rng()-0.5)*40;\n          suns.push({x:p.cx+ox, y:p.cy-15, ty:p.cy+20, vy:-0.38, g:0.0014, bounced:0, anim:now, life:SUN_LIVE_TIME, falling:false, bouncing:true});\n        }\n      } else if(p.type === \"peashooter\"){\n        let hasZ = false;\n        for(const z of zombies){ if(z.row===y && !z.dead && z.x > p.cx){ hasZ=true; break; } }\n        if(hasZ){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now});\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"repeaterpea\"){\n        if(p.secondShotT > 0){\n          p.secondShotT -= dt;\n          if(p.secondShotT <= 0){\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now});\n            p.secondShotT = 0;\n          }\n        }\n        let hasZ2 = false;\n        for(const z of zombies){ if(z.row===y && !z.dead && z.x > p.cx){ hasZ2=true; break; } }\n        if(hasZ2){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now});\n            p.secondShotT = 100;\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"snowpea\"){\n        let hasZ = false;\n        for(const z of zombies){ if(z.row===y && !z.dead && z.x > p.cx){ hasZ=true; break; } }\n        if(hasZ){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            bullets.push({x:p.cx+18, y:p.cy-6, row:y, dmg:BULLET_DAMAGE, anim:now, ice:true});\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"threepeater\"){\n        let hasZ3 = false;\n        for(let dy=-1;dy<=1;dy++){\n          const ry = y + dy;\n          if(ry < 0 || ry >= ROWS) continue;\n          for(const z of zombies){ if(z.row===ry && !z.dead && z.x > p.cx){ hasZ3=true; break; } }\n        }\n        if(hasZ3){\n          p.shootTimer -= dt;\n          if(p.shootTimer <= 0){\n            p.shootTimer = PEA_INTERVAL;\n            for(let dy=-1;dy<=1;dy++){\n              const ry = y + dy;\n              if(ry < 0 || ry >= ROWS) continue;\n              const ty = GRID_Y+ry*CELL_H+CELL_H/2-6;\n              bullets.push({x:p.cx+18, y:p.cy-6, startY:p.cy-6, targetY:ty, startX:p.cx+18, row:ry, dmg:BULLET_DAMAGE, anim:now});\n            }\n          }\n        } else {\n          p.shootTimer = Math.min(p.shootTimer, PEA_FIRST_DELAY);\n        }\n      } else if(p.type === \"chomper\"){\n        if(p.chewing){\n          p.chewTimer -= dt;\n          if(p.chewTimer <= 0) p.chewing = false;\n        } else {\n          for(const z of zombies){\n            if(!z.dead && z.row===y && z.x > p.cx && z.x - p.cx < CELL_W*1.8){\n              z.hp = 0; z.dead = true;\n              spawnParticle(z.x, z.y, \"#9a5ab8\", 12);\n              p.chewing = true;\n              p.chewTimer = 30000;\n              break;\n            }\n          }\n        }\n      } else if(p.type === \"potatomine\"){\n        if(!p.armed){\n          p.armTimer -= dt;\n          if(p.armTimer <= 0) p.armed = true;\n        } else {\n          for(const z of zombies){\n            if(!z.dead && z.row===y && Math.abs(z.x - p.cx) < 30){\n              explode(p.cx, p.cy, POTATO_DAMAGE, y, 1);\n              p.hp = 0;\n              break;\n            }\n          }\n        }\n      } else if(p.type === \"cherrybomb\"){\n        p.fuse -= dt;\n        if(p.fuse <= 0){\n          explode(p.cx, p.cy, CHERRY_DAMAGE, y, 3);\n          p.hp = 0;\n        }\n      }\n    }\n  }\n  for(let y=0;y<ROWS;y++){\n    for(let x=0;x<COLS;x++){\n      if(grid[y][x] && grid[y][x].hp <= 0) grid[y][x] = null;\n    }\n  }\n\n  /* 子弹更新 */\n  for(let i=bullets.length-1;i>=0;i--){\n    const b = bullets[i];\n    b.x += BULLET_SPEED*dt/1000;\n    b.anim = now;\n    if(b.targetY !== undefined){\n      const t = Math.min(1, (b.x - b.startX) / (CELL_W * 0.6));\n      b.y = b.startY + (b.targetY - b.startY) * t;\n    }\n    if(b.x > SPAWN_X+20){ bullets.splice(i,1); continue; }\n    for(const z of zombies){\n      if(z.dead || z.row !== b.row) continue;\n      if(Math.abs(z.x - b.x) < 16){\n        damageZombie(z, b.dmg);\n        z.hitFlash = 100;\n        if(b.ice) z.slowed = 5000;\n        bullets.splice(i,1);\n        spawnParticle(b.x, b.y, z.helmet>0?((z.kind===\"buckethead\"||z.kind===\"football\"||z.kind===\"screendoor\")?\"#aaa\":(z.kind===\"newspaper\"?\"#d8c8a0\":\"#e8822a\")):\"#a8e07a\", 4);\n        break;\n      }\n    }\n  }\n\n  /* 僵尸更新 */\n  for(let i=zombies.length-1;i>=0;i--){\n    const z = zombies[i];\n    if(z.dead){ zombies.splice(i,1); continue; }\n    z.anim = now;\n    if(z.hitFlash>0) z.hitFlash -= dt;\n\n    /* 撑杆跳跳跃中 */\n    if(z.jumping){\n      z.jumpProgress += dt/600;\n      z.x -= CELL_W*1.5*dt/600;\n      if(z.jumpProgress >= 1){\n        z.jumping = false;\n        z.jumpProgress = 0;\n        z.hasPole = false;\n      }\n      continue;\n    }\n\n    /* 检测前方植物 */\n    let target = null;\n    for(let x=0;x<COLS;x++){\n      const p = grid[z.row][x];\n      if(p && Math.abs(z.x - p.cx) < 28){ target = {p:p, x:x}; break; }\n    }\n\n    /* 撑杆跳僵尸有杆子时跳过第一个植物 */\n    if(target && z.hasPole && z.kind === \"polevaulter\"){\n      z.jumping = true;\n      z.jumpProgress = 0;\n      continue;\n    }\n\n    if(target){\n      z.attackT -= dt;\n      if(z.attackT <= 0){\n        z.attackT = ZOMBIE_ATTACK_INTERVAL;\n        target.p.hp -= ZOMBIE_DAMAGE;\n      }\n    } else {\n      if(z.kind===\"newspaper\" && z.helmet<=0 && !z.enraged){ z.enraged = true; }\n      let spd = ZOMBIE_SPEED;\n      if(z.kind===\"polevaulter\" && z.hasPole) spd = ZOMBIE_SPEED*1.5;\n      else if(ZOMBIE_TYPES[z.kind] && ZOMBIE_TYPES[z.kind].speed) spd = ZOMBIE_SPEED * ZOMBIE_TYPES[z.kind].speed;\n      if(z.enraged) spd *= 2;\n      if(z.slowed > 0){ z.slowed -= dt; spd *= 0.5; }\n      z.x -= spd*dt/1000;\n      if(z.x < HOUSE_X){\n        const my = z.row;\n        if(mowers[my]){\n          mowers[my] = false;\n          mowerEntities.push({\n            x: GRID_X - 30, cy: GRID_Y + my*CELL_H + CELL_H/2,\n            row: my, anim: now\n          });\n        } else {\n          lose();\n          return;\n        }\n      }\n    }\n    if(z.hp <= 0){\n      z.dead = true;\n      spawnParticle(z.x, z.y, \"#b5c098\", 6);\n      actionLog.push({t:now, e:\"kill\"});\n    }\n  }\n\n  /* 割草机行驶 */\n  for(let i=mowerEntities.length-1;i>=0;i--){\n    const m = mowerEntities[i];\n    m.anim = now;\n    m.x += MOWER_SPEED*dt/1000;\n    for(const z of zombies){\n      if(!z.dead && z.row===m.row && Math.abs(z.x - (m.x+11)) < 22){\n        z.hp = 0; z.dead = true;\n        spawnParticle(z.x, z.y, \"#b5c098\", 6);\n      }\n    }\n    if(rng() < 0.25){ spawnParticle(m.x+4, m.cy+6, \"#7ec850\", 1); }\n    if(m.x > W + 30) mowerEntities.splice(i,1);\n  }\n\n  /* 粒子更新 */\n  for(let i=particles.length-1;i>=0;i--){\n    const p = particles[i];\n    p.x += p.vx*dt/1000; p.y += p.vy*dt/1000;\n    p.vy += 200*dt/1000;\n    p.life -= dt;\n    if(p.life <= 0) particles.splice(i,1);\n  }\n\n  /* 胜利判定 */\n  if(waveIndex >= NUM_FLAGS*10 && zombies.length === 0 && zombiesToSpawn.length === 0){\n    win();\n  }\n}\nlet mowers = [true,true,true,true,true];\n\n/* 对僵尸造成伤害：先扣防具，再扣本体 */\nfunction damageZombie(z, dmg){\n  if(z.helmet > 0){\n    z.helmet -= dmg;\n    if(z.helmet < 0){ z.hp += z.helmet; z.helmet = 0; }\n  } else {\n    z.hp -= dmg;\n  }\n  if(z.hp <= 0) z.dead = true;\n}\n\nfunction explode(cx, cy, dmg, row, range){\n  spawnParticle(cx, cy, \"#ff8c42\", 20);\n  spawnParticle(cx, cy, \"#ffd24a\", 15);\n  if(range === 1){\n    for(const z of zombies){ if(!z.dead && z.row===row && Math.abs(z.x-cx)<50){ damageZombie(z, dmg); } }\n  } else {\n    for(const z of zombies){\n      if(z.dead) continue;\n      if(Math.abs(z.x-cx) < CELL_W*1.5 && Math.abs(z.y-cy) < CELL_H*1.5){\n        damageZombie(z, dmg);\n      }\n    }\n  }\n}\nfunction spawnParticle(x,y,color,n){\n  for(let i=0;i<n;i++){\n    const a = rng()*Math.PI*2, sp = 40+rng()*120;\n    particles.push({x:x,y:y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-40,color:color,size:2+rng()*4,life:400+rng()*300,maxLife:700});\n  }\n}\n\n/* ===== 渲染 ===== */\n/* 开始游戏按钮 */\nconst START_BTN  = { w:280, h:64, get x(){return W/2-this.w/2;}, get y(){return H/2-this.h/2+30;} };\nconst WEEKLY_BTN = { w:280, h:56, get x(){return W/2-this.w/2;}, get y(){return START_BTN.y + START_BTN.h + 18;} };\nconst LB_BTN     = { w:220, h:46, get x(){return W/2-this.w/2;}, get y(){return WEEKLY_BTN.y + WEEKLY_BTN.h + 22;} };\nconst BACK_BTN   = { w:120, h:42, get x(){return W/2-this.w/2;}, get y(){return H-60;} };\n/* 暂停按钮（右上角，阳光框左侧）+ 暂停面板 */\nconst PAUSE_BTN   = { w:40, h:36, x: W-176, y: 10 };\nconst PAUSE_PANEL = { w:320, h:210, get x(){return W/2-this.w/2;}, get y(){return H/2-this.h/2;} };\nconst RESUME_BTN  = { w:240, h:52, get x(){return W/2-this.w/2;}, get y(){return PAUSE_PANEL.y+74;} };\nconst PMENU_BTN   = { w:240, h:52, get x(){return W/2-this.w/2;}, get y(){return RESUME_BTN.y+RESUME_BTN.h+18;} };\n\nfunction drawMenu(now){\n  ctx.clearRect(0,0,W,H);\n  drawBackground();\n  ctx.fillStyle = \"rgba(50,40,30,.55)\";\n  ctx.fillRect(0,0,W,H);\n  for(let i=0;i<3;i++){\n    const sx = 180 + i*280 + Math.sin(now*0.0008+i)*30;\n    const sy = 80 + Math.cos(now*0.0006+i*2)*20;\n    ctx.save(); ctx.globalAlpha = 0.4;\n    drawSun({x:sx, y:sy, anim:now+i*1000});\n    ctx.restore();\n  }\n  ctx.textAlign = \"center\";\n  ctx.fillStyle = \"rgba(0,0,0,.3)\";\n  ctx.font = \"bold 44px sans-serif\";\n  ctx.fillText(\"植物大战僵尸\", W/2+2, 92);\n  ctx.fillStyle = \"#fff\";\n  ctx.fillText(\"植物大战僵尸\", W/2, 90);\n  ctx.font = \"bold 18px sans-serif\";\n  ctx.fillStyle = \"#ffd24a\";\n  ctx.fillText(\"白天 1-5 · 终极挑战\", W/2, 120);\n\n  /* 开始游戏按钮 */\n  const b = START_BTN;\n  const hover = mouse.x>=b.x && mouse.x<=b.x+b.w && mouse.y>=b.y && mouse.y<=b.y+b.h;\n  ctx.save();\n  if(hover) ctx.translate(0, -3);\n  const g = ctx.createLinearGradient(0, b.y, 0, b.y+b.h);\n  if(hover){ g.addColorStop(0,\"#ffb347\"); g.addColorStop(1,\"#ff8c42\"); }\n  else { g.addColorStop(0,\"#7ec850\"); g.addColorStop(1,\"#5aa530\"); }\n  ctx.fillStyle = g;\n  ctx.beginPath(); ctx.roundRect(b.x, b.y, b.w, b.h, 16); ctx.fill();\n  ctx.strokeStyle = \"rgba(255,255,255,.5)\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.roundRect(b.x+2, b.y+2, b.w-4, b.h-4, 14); ctx.stroke();\n  ctx.shadowColor = \"rgba(0,0,0,.25)\"; ctx.shadowBlur = 8; ctx.shadowOffsetY = 3;\n  ctx.fillStyle = \"#fff\";\n  ctx.font = \"bold 30px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(\"开始游戏\", W/2, b.y+b.h/2+10);\n  ctx.restore();\n\n  /* 每周挑战按钮 */\n  const wb = WEEKLY_BTN;\n  const hoverW = mouse.x>=wb.x && mouse.x<=wb.x+wb.w && mouse.y>=wb.y && mouse.y<=wb.y+wb.h;\n  ctx.save();\n  if(hoverW) ctx.translate(0, -3);\n  const gw = ctx.createLinearGradient(0, wb.y, 0, wb.y+wb.h);\n  if(hoverW){ gw.addColorStop(0,\"#b07ce8\"); gw.addColorStop(1,\"#7a4ec0\"); }\n  else { gw.addColorStop(0,\"#8a5ec8\"); gw.addColorStop(1,\"#5a3a98\"); }\n  ctx.fillStyle = gw;\n  ctx.beginPath(); ctx.roundRect(wb.x, wb.y, wb.w, wb.h, 14); ctx.fill();\n  ctx.strokeStyle = \"rgba(255,255,255,.5)\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.roundRect(wb.x+2, wb.y+2, wb.w-4, wb.h-4, 12); ctx.stroke();\n  ctx.fillStyle = \"#fff\";\n  ctx.font = \"bold 24px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(\"⚔ 每周挑战\", W/2, wb.y+25);\n  ctx.font = \"13px sans-serif\"; ctx.fillStyle = \"rgba(255,255,255,.85)\";\n  ctx.fillText(window.__WEEK__ ? (\"本周 \" + window.__WEEK__.id + \" · 僵尸阵容轮换\") : \"僵尸阵容每周轮换\", W/2, wb.y+wb.h-11);\n  ctx.restore();\n\n  /* 排行榜按钮 */\n  const lb2 = LB_BTN;\n  const hover2 = mouse.x>=lb2.x && mouse.x<=lb2.x+lb2.w && mouse.y>=lb2.y && mouse.y<=lb2.y+lb2.h;\n  ctx.save();\n  if(hover2) ctx.translate(0,-2);\n  ctx.fillStyle = hover2 ? \"rgba(255,255,255,.25)\" : \"rgba(255,255,255,.15)\";\n  ctx.beginPath(); ctx.roundRect(lb2.x, lb2.y, lb2.w, lb2.h, 24); ctx.fill();\n  ctx.strokeStyle = \"rgba(255,255,255,.5)\"; ctx.lineWidth = 2;\n  ctx.beginPath(); ctx.roundRect(lb2.x+1, lb2.y+1, lb2.w-2, lb2.h-2, 23); ctx.stroke();\n  ctx.fillStyle = \"#fff\";\n  ctx.font = \"bold 20px sans-serif\"; ctx.textAlign = \"center\";\n  ctx.fillText(\"🏆 通关排行榜\", W/2, lb2.y+lb2.h/2+7);\n  ctx.restore();\n}\n\n/* 排行榜面板 */\nfunction drawLeaderboard(now){\n  ctx.clearRect(0,0,W,H);\n  drawBackground();\n  ctx.fillStyle = \"rgba(50,40,30,.6)\";\n  ctx.fillRect(0,0,W,H);\n  const pw=460, ph=440, px=W/2-pw/2, py=H/2-ph/2-10;\n  ctx.fillStyle = \"rgba(250,240,220,.96)\";\n  ctx.beginPath(); ctx.roundRect(px,py,pw,ph,16); ctx.fill();\n  ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth=3;\n  ctx.beginPath(); ctx.roundRect(px,py,pw,ph,16); ctx.stroke();\n  ctx.textAlign=\"center\";\n  ctx.fillStyle=\"#8b5a2b\"; ctx.font=\"bold 26px sans-serif\";\n  ctx.fillText(lbTab===\"clears\" ? \"🏆 通关次数排行榜\" : (\"☀ 本周排行榜 · \" + (window.__WEEK__?window.__WEEK__.id:\"\")), W/2, py+40);\n  /* Tab 按钮 */\n  const tabH=32, tabY=py+54;\n  const tabs = [\n    { key:\"clears\", label:\"🏆 通关次数\", x: px+pw/2-168 },\n    { key:\"sun\",    label:\"☀ 本周排行\", x: px+pw/2+8 }\n  ];\n  tabs.forEach(t=>{\n    t.w=160; t.y=tabY; t.h=tabH;\n    const hover = mouse.x>=t.x&&mouse.x<=t.x+t.w&&mouse.y>=t.y&&mouse.y<=t.y+t.h;\n    const active = lbTab===t.key;\n    ctx.fillStyle = active ? \"#8b5a2b\" : (hover ? \"rgba(139,90,43,.18)\" : \"rgba(139,90,43,.06)\");\n    ctx.beginPath(); ctx.roundRect(t.x,t.y,t.w,t.h,8); ctx.fill();\n    ctx.fillStyle = active ? \"#fff\" : \"#8b5a2b\";\n    ctx.font=\"bold 15px sans-serif\";\n    ctx.fillText(t.label, t.x+t.w/2, t.y+t.h/2+5);\n  });\n  const lb = lbTab===\"clears\" ? (window.__LEADERBOARD__||[]) : (window.__WEEK_LEADERBOARD__||[]);\n  const valKey = lbTab===\"clears\" ? \"count\" : \"sun\";\n  const valSuffix = lbTab===\"clears\" ? \" 次\" : \" ☀\";\n  if(lb.length === 0){\n    ctx.fillStyle=\"#999\"; ctx.font=\"18px sans-serif\";\n    ctx.fillText(lbTab===\"clears\" ? \"暂无通关记录\" : \"本周暂无排行记录\", W/2, py+ph/2-10);\n    ctx.font=\"14px sans-serif\";\n    ctx.fillText(lbTab===\"clears\" ? \"快来成为第一个通关的人！\" : \"参与每周挑战通关即可上榜！\", W/2, py+ph/2+18);\n  } else {\n    ctx.textAlign=\"left\";\n    lb.forEach((e,i)=>{\n      const ry = py+112+i*28;\n      if(i<3){ ctx.fillStyle=\"rgba(255,210,74,.2)\"; ctx.fillRect(px+20,ry-18,pw-40,24); }\n      const medal = i===0?\"🥇\":i===1?\"🥈\":i===2?\"🥉\":(i+1)+\".\";\n      ctx.fillStyle = i<3?\"#d4880f\":\"#888\"; ctx.font=\"bold 16px sans-serif\";\n      ctx.fillText(medal, px+34, ry);\n      ctx.fillStyle=\"#333\"; ctx.font=\"16px sans-serif\";\n      const name = (e.name||\"匿名\").length>12 ? (e.name||\"匿\").slice(0,12)+\"…\" : (e.name||\"匿名\");\n      ctx.fillText(name, px+78, ry);\n      ctx.textAlign=\"right\";\n      ctx.fillStyle=\"#d4880f\"; ctx.font=\"bold 16px sans-serif\";\n      ctx.fillText((e[valKey]||0) + valSuffix, px+pw-34, ry);\n      ctx.textAlign=\"left\";\n    });\n  }\n  ctx.textAlign=\"center\";\n  const bb = BACK_BTN;\n  ctx.fillStyle=\"#a08060\"; ctx.font=\"13px sans-serif\";\n  ctx.fillText(lbTab===\"clears\"\n    ? \"只有通关第五关才会记入排行榜\"\n    : (\"本周 \" + (window.__WEEK__?window.__WEEK__.id:\"\") + \" · 每周挑战通关收集的阳光可累积 · 每周一刷新\"),\n    W/2, bb.y-12);\n  const hb = mouse.x>=bb.x && mouse.x<=bb.x+bb.w && mouse.y>=bb.y && mouse.y<=bb.y+bb.h;\n  ctx.fillStyle = hb?\"#c97a30\":\"#b8702a\";\n  ctx.beginPath(); ctx.roundRect(bb.x,bb.y,bb.w,bb.h,20); ctx.fill();\n  ctx.fillStyle=\"#fff\"; ctx.font=\"bold 18px sans-serif\";\n  ctx.fillText(\"返回\", W/2, bb.y+bb.h/2+6);\n}\n\nfunction render(now){\n  if(state === \"menu\"){ drawMenu(now); return; }\n  if(state === \"leaderboard\"){ drawLeaderboard(now); return; }\n  ctx.clearRect(0,0,W,H);\n  drawBackground();\n  if(selected && mouse.x>0){\n    const cell = cellAt(mouse.x, mouse.y);\n    if(cell){\n      const c = cellCenter(cell.x, cell.y);\n      ctx.fillStyle = (grid[cell.y][cell.x] || sun < PLANTS[selected].cost) ? \"rgba(200,60,60,.25)\" : \"rgba(255,255,200,.35)\";\n      ctx.fillRect(GRID_X+cell.x*CELL_W, GRID_Y+cell.y*CELL_H, CELL_W, CELL_H);\n      ctx.strokeStyle = \"rgba(90,140,50,.6)\"; ctx.lineWidth = 2;\n      ctx.strokeRect(GRID_X+cell.x*CELL_W+1, GRID_Y+cell.y*CELL_H+1, CELL_W-2, CELL_H-2);\n    }\n  }\n  if(shovelActive && mouse.x>0){\n    const cell = cellAt(mouse.x, mouse.y);\n    if(cell && grid[cell.y][cell.x]){\n      ctx.fillStyle = \"rgba(200,140,40,.3)\";\n      ctx.fillRect(GRID_X+cell.x*CELL_W, GRID_Y+cell.y*CELL_H, CELL_W, CELL_H);\n    }\n  }\n  for(let y=0;y<ROWS;y++){\n    for(let x=0;x<COLS;x++){\n      const p = grid[y][x];\n      if(p) drawPlant(p, p.cx, p.cy);\n    }\n  }\n  for(const s of suns) drawSun(s);\n  for(const b of bullets) drawBullet(b);\n  for(const z of zombies){ if(z.hitFlash>0){ ctx.globalAlpha=0.6; } drawZombie(z); ctx.globalAlpha=1; }\n  for(const m of mowerEntities) drawMowerBody(m.x, m.cy);\n  for(const p of particles) drawParticle(p);\n  drawUI(now);\n  /* 暂停面板 */\n  if(paused){\n    ctx.fillStyle = \"rgba(20,15,10,.55)\";\n    ctx.fillRect(0,0,W,H);\n    const pp = PAUSE_PANEL;\n    ctx.fillStyle = \"#fef3e2\";\n    ctx.strokeStyle = \"#8b5a2b\"; ctx.lineWidth = 3;\n    ctx.beginPath(); ctx.roundRect(pp.x, pp.y, pp.w, pp.h, 16); ctx.fill(); ctx.stroke();\n    ctx.fillStyle = \"#8b5a2b\";\n    ctx.font = \"bold 30px sans-serif\"; ctx.textAlign = \"center\";\n    ctx.fillText(\"已暂停\", W/2, pp.y+48);\n    const pbtns = [[RESUME_BTN,\"▶ 继续游戏\",\"#7ec850\",\"#5aa530\"],[PMENU_BTN,\"🏠 返回主菜单\",\"#e0a030\",\"#c08020\"]];\n    for(const it of pbtns){\n      const bb = it[0];\n      const hover = mouse.x>=bb.x&&mouse.x<=bb.x+bb.w&&mouse.y>=bb.y&&mouse.y<=bb.y+bb.h;\n      ctx.save();\n      if(hover) ctx.translate(0,-2);\n      const g = ctx.createLinearGradient(0,bb.y,0,bb.y+bb.h);\n      g.addColorStop(0, hover?\"#9ee070\":it[1+1]); g.addColorStop(1, hover?\"#7ec850\":it[1+2]);\n      ctx.fillStyle = g;\n      ctx.beginPath(); ctx.roundRect(bb.x, bb.y, bb.w, bb.h, 12); ctx.fill();\n      ctx.fillStyle = \"#fff\";\n      ctx.font = \"bold 20px sans-serif\";\n      ctx.fillText(it[1], bb.x+bb.w/2, bb.y+bb.h/2+7);\n      ctx.restore();\n    }\n  }\n}\n\n/* ===== 输入 ===== */\nfunction getMouse(e){\n  const r = C.getBoundingClientRect();\n  return {\n    x: (e.clientX - r.left) * (W / r.width),\n    y: (e.clientY - r.top) * (H / r.height)\n  };\n}\nC.addEventListener(\"mousemove\", e=>{ const m=getMouse(e); mouse.x=m.x; mouse.y=m.y; });\nC.addEventListener(\"mouseleave\", ()=>{ mouse.x=-1; mouse.y=-1; });\nC.addEventListener(\"click\", e=>{\n  const m = getMouse(e); mouse.x=m.x; mouse.y=m.y;\n  /* 暂停面板：继续 / 返回主菜单 */\n  if(paused){\n    const rb = RESUME_BTN;\n    if(m.x>=rb.x&&m.x<=rb.x+rb.w&&m.y>=rb.y&&m.y<=rb.y+rb.h){ paused=false; return; }\n    const mb = PMENU_BTN;\n    if(m.x>=mb.x&&m.x<=mb.x+mb.w&&m.y>=mb.y&&m.y<=mb.y+mb.h){ paused=false; state=\"menu\"; return; }\n    return;\n  }\n  /* 菜单状态：开始游戏 + 排行榜 */\n  if(state === \"menu\"){\n    const b = START_BTN;\n    if(m.x>=b.x && m.x<=b.x+b.w && m.y>=b.y && m.y<=b.y+b.h){\n      newGame(window.__SEED__, 0);\n      return;\n    }\n    const wb = WEEKLY_BTN;\n    if(m.x>=wb.x && m.x<=wb.x+wb.w && m.y>=wb.y && m.y<=wb.y+wb.h){\n      newGame(window.__SEED__, 0, \"weekly\");\n      return;\n    }\n    const lb = LB_BTN;\n    if(m.x>=lb.x && m.x<=lb.x+lb.w && m.y>=lb.y && m.y<=lb.y+lb.h){\n      state = \"leaderboard\";\n    }\n    return;\n  }\n  if(state === \"leaderboard\"){\n    const pw=460, ph=440, px=W/2-pw/2, py=H/2-ph/2-10;\n    const tabY=py+54;\n    const tabDefs = [[\"clears\", px+pw/2-168],[\"sun\", px+pw/2+8]];\n    for(const td of tabDefs){\n      if(m.x>=td[1] && m.x<=td[1]+160 && m.y>=tabY && m.y<=tabY+32){ lbTab = td[0]; return; }\n    }\n    const bb = BACK_BTN;\n    if(m.x>=bb.x && m.x<=bb.x+bb.w && m.y>=bb.y && m.y<=bb.y+bb.h){\n      state = \"menu\";\n    }\n    return;\n  }\n  if(state !== \"play\") return;\n  /* 右上角暂停按钮 */\n  {\n    const pb = PAUSE_BTN;\n    if(m.x>=pb.x&&m.x<=pb.x+pb.w&&m.y>=pb.y&&m.y<=pb.y+pb.h){ paused=true; return; }\n  }\n  if(m.x >= W-130 && m.x <= W-16 && m.y >= 10 && m.y <= 46){\n    sunClickCount++;\n    if(sunClickCount >= 3){\n      cheatInput.style.display = \"block\";\n      cheatInput.focus();\n      sunClickCount = 0;\n    }\n    return;\n  }\n  let collectedAny = false;\n  for(let i=suns.length-1;i>=0;i--){\n    const s = suns[i];\n    if(!s.flying && Math.hypot(s.x-m.x, s.y-m.y) < 28){\n      s.flying = true;\n      s.flyT = 0;\n      s.flyDur = 300 + Math.hypot(s.x-SUN_BOX_X, s.y-SUN_BOX_Y)*0.4;\n      s.fromX = s.x; s.fromY = s.y;\n      s.toX = SUN_BOX_X; s.toY = SUN_BOX_Y;\n      s.falling = false;\n      spawnParticle(s.x, s.y, \"#ffd24a\", 6);\n      collectedAny = true;\n    }\n  }\n  if(collectedAny) return;\n  const cardX0 = 16, cardY = 10, cardW = 60, cardH = 78, gap = 6;\n  if(m.x >= cardX0 && m.y >= cardY && m.y <= cardY+cardH){\n    curCardOrder.forEach((key, i)=>{\n      const x = cardX0 + i*(cardW+gap);\n      if(m.x >= x && m.x <= x+cardW){\n        if(cardCd[key] > performance.now() || sun < PLANTS[key].cost) return;\n        selected = (selected===key) ? null : key;\n        shovelActive = false;\n      }\n    });\n    const shX = cardX0 + curCardOrder.length*(cardW+gap) + 8;\n    if(m.x >= shX && m.x <= shX+48){\n      shovelActive = !shovelActive;\n      selected = null;\n    }\n    return;\n  }\n  const cell = cellAt(m.x, m.y);\n  if(cell){\n    if(shovelActive){\n      if(grid[cell.y][cell.x]){\n        grid[cell.y][cell.x] = null;\n        shovelActive = false;\n        actionLog.push({t:performance.now(), e:\"shovel\", x:cell.x, y:cell.y});\n      }\n    } else if(selected){\n      if(!grid[cell.y][cell.x] && sun >= PLANTS[selected].cost && cardCd[selected] <= performance.now()){\n        const c = cellCenter(cell.x, cell.y);\n        const def = PLANTS[selected];\n        const p = { type:selected, cx:c.x, cy:c.y+4, hp:def.hp, anim:performance.now() };\n        if(selected===\"peashooter\" || selected===\"repeaterpea\" || selected===\"snowpea\" || selected===\"threepeater\") p.shootTimer = PEA_FIRST_DELAY;\n        if(selected===\"repeaterpea\") p.secondShotT = 0;\n        if(selected===\"chomper\"){ p.chewing=false; p.chewTimer=0; }\n        if(selected===\"sunflower\") p.sunTimer = SUNFLOWER_FIRST;\n        if(selected===\"potatomine\"){ p.armed=false; p.armTimer=POTATO_ARM_TIME; }\n        if(selected===\"cherrybomb\") p.fuse = CHERRY_FUSE;\n        grid[cell.y][cell.x] = p;\n        sun -= def.cost;\n        cardCd[selected] = performance.now() + def.cd;\n        actionLog.push({t:performance.now(), e:\"plant\", type:selected, x:cell.x, y:cell.y});\n        selected = null;\n        spawnParticle(c.x, c.y+10, \"#7ec850\", 6);\n      }\n    }\n  }\n});\n\n/* ===== 胜负 ===== */\nfunction win(){\n  state = \"won\";\n  paused = false;\n  ovTitle.textContent = \"通关成功！\";\n  ovText.textContent = gameMode === \"weekly\"\n    ? (\"本周挑战通关！收集阳光 \" + collectedSun + \" 已记入周榜，多打多累积！\")\n    : \"你守护了家园，消灭了全部僵尸。排行榜已更新！\";\n  ovBtn.textContent = \"刷新查看排行榜\";\n  fillLeaderboardHTML();\n  overlay.classList.add(\"show\");\n  if(window.community && window.community.call){\n    window.community.call(\"finish\", {seed:gameSeed, actions:actionLog, result:\"win\", level:curLevel, mode:gameMode, collectedSun:collectedSun, week:(window.__WEEK__&&window.__WEEK__.id)});\n  }\n}\nfunction lose(){\n  state = \"lost\";\n  paused = false;\n  ovTitle.textContent = \"游戏失败\";\n  ovText.textContent = \"僵尸吃掉了你的脑子！再试一次吧。\";\n  ovBtn.textContent = \"重试\";\n  fillLeaderboardHTML();\n  overlay.classList.add(\"show\");\n  if(window.community && window.community.call){\n    window.community.call(\"finish\", {seed:gameSeed, actions:actionLog, result:\"lose\", level:curLevel, mode:gameMode, collectedSun:collectedSun, week:(window.__WEEK__&&window.__WEEK__.id)});\n  }\n}\novBtn.addEventListener(\"click\", ()=>{\n  if(state === \"won\"){ location.reload(); }\n  else { newGame(window.__SEED__, curLevel, gameMode); }\n});\n/* 作弊：在随机一路召唤指定类型僵尸 */\nfunction spawnCheatZombie(kind){\n  if(state !== \"play\") return;\n  const row = Math.floor(rng()*ROWS);\n  const cy = GRID_Y + row*CELL_H + CELL_H/2 + 6;\n  const zt = ZOMBIE_TYPES[kind] || ZOMBIE_TYPES.normal;\n  zombies.push({\n    x: SPAWN_X + rng()*30, y: cy, row:row, kind:kind,\n    hp: zt.hp, helmet: zt.helmet, maxHelmet: zt.helmet,\n    anim: performance.now(), walkT:0, attackT:0, attackTarget:null, dead:false,\n    hasPole: false, jumping:false, jumpProgress:0,\n    slowed: 0, enraged: false\n  });\n}\ncheatInput.addEventListener(\"keydown\", e=>{\n  if(e.key === \"Enter\"){\n    if(cheatInput.value === \"zard666\"){\n      cheatInput.value = \"\";\n      cheatInput.style.display = \"none\";\n      win();\n    } else if(cheatInput.value === \"zard999\"){\n      sun = 999;\n      cheatInput.value = \"\";\n      cheatInput.style.display = \"none\";\n    } else if(cheatInput.value === \"zarddb\"){\n      spawnCheatZombie(\"newspaper\");\n      cheatInput.value = \"\"; cheatInput.style.display = \"none\";\n    } else if(cheatInput.value === \"zardglq\"){\n      spawnCheatZombie(\"football\");\n      cheatInput.value = \"\"; cheatInput.style.display = \"none\";\n    } else if(cheatInput.value === \"zardtw\"){\n      spawnCheatZombie(\"screendoor\");\n      cheatInput.value = \"\"; cheatInput.style.display = \"none\";\n    } else {\n      cheatInput.style.display = \"none\";\n      cheatInput.value = \"\";\n    }\n  }\n  if(e.key === \"Escape\"){\n    cheatInput.style.display = \"none\";\n    cheatInput.value = \"\";\n  }\n  e.stopPropagation();\n});\ncheatInput.addEventListener(\"blur\", ()=>{\n  cheatInput.style.display = \"none\";\n  cheatInput.value = \"\";\n});\n\n/* ===== 主循环 ===== */\nfunction loop(t){\n  if(!lastTime) lastTime = t;\n  const dt = Math.min(t - lastTime, 50);\n  lastTime = t;\n  update(dt, t);\n  render(t);\n  requestAnimationFrame(loop);\n}\n\n/* polyfill: roundRect */\nif(!ctx.roundRect){\n  CanvasRenderingContext2D.prototype.roundRect = function(x,y,w,h,r){\n    if(typeof r===\"number\") r={tl:r,tr:r,br:r,bl:r};\n    this.beginPath();\n    this.moveTo(x+r.tl,y);\n    this.lineTo(x+w-r.tr,y); this.quadraticCurveTo(x+w,y,x+w,y+r.tr);\n    this.lineTo(x+w,y+h-r.br); this.quadraticCurveTo(x+w,y+h,x+w-r.br,y+h);\n    this.lineTo(x+r.bl,y+h); this.quadraticCurveTo(x,y+h,x,y+h-r.bl);\n    this.lineTo(x,y+r.tl); this.quadraticCurveTo(x,y,x+r.tl,y);\n    this.closePath();\n    return this;\n  };\n}\n\nstate = \"menu\";\nmouse = {x:-1, y:-1, click:false};\n/* 本地预览 fallback：服务端未注入 __WEEK__ 时，按当前日期生成（服务端注入会覆盖） */\nif(!window.__WEEK__){\n  const _wy = isoWeek(new Date());\n  window.__WEEK__ = { id: _wy, zombies: weeklyZombieSet(_wy) };\n}\nif(!window.__WEEK_LEADERBOARD__) window.__WEEK_LEADERBOARD__ = [];\nmowers = [true,true,true,true,true];\nmowerEntities = [];\n/* 快捷键：ESC / P 切换暂停（输入框聚焦时不触发） */\nwindow.addEventListener(\"keydown\", e=>{\n  if(document.activeElement && document.activeElement.tagName === \"INPUT\") return;\n  if(state === \"play\" && (e.key === \"Escape\" || e.key === \"p\" || e.key === \"P\")){\n    paused = !paused;\n    e.preventDefault();\n  }\n});\nrequestAnimationFrame(loop);\n";

// 服务端工具：ISO 周数 + 每周僵尸组合（须与前端 index.html 实现完全一致）
function _rng(seed){ let s = seed >>> 0 || 1; return function(){ s = (s*1664525+1013904223)>>>0; return s/4294967296; }; }
function isoWeek(d){
  const date = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(),0,1));
  const weekNum = Math.ceil((((date - yearStart)/86400000) + 1)/7);
  return date.getUTCFullYear() + "W" + String(weekNum).padStart(2,"0");
}
function weeklyZombieSet(yearWeek){
  return ["normal","flag","newspaper","football","screendoor","conehead","buckethead","polevaulter"];
}

// render 返回标题 + 通关排行榜，webview iframe 在其下方渲染。
export async function render(ctx, api) {
  let best = 0;
  try { best = (await api.kv.get("best")) ?? 0; } catch(e) {}

  // 读取共享区排行榜（通关次数榜 + 当周阳光榜）
  const yearWeek = isoWeek(new Date());
  let leaderboard = [];
  let weekLeaderboard = [];
  try {
    const all = await api.kv.listPublic();
    const entries = [];
    const sunEntries = [];
    const wPrefix = "wsun_" + yearWeek + "_";
    const wnPrefix = "wname_" + yearWeek + "_";
    for (const k of Object.keys(all)) {
      if (k.startsWith("clear_")) {
        const uid = k.slice(6);
        const name = all["name_" + uid] || "匿名玩家";
        const count = parseInt(all[k]) || 0;
        entries.push({ name, count });
      } else if (k.startsWith(wPrefix)) {
        const uid = k.slice(wPrefix.length);
        const name = all[wnPrefix + uid] || "匿名玩家";
        const sun = parseInt(all[k]) || 0;
        sunEntries.push({ name, sun });
      }
    }
    entries.sort((a, b) => b.count - a.count);
    leaderboard = entries.slice(0, 10);
    sunEntries.sort((a, b) => b.sun - a.sun);
    weekLeaderboard = sunEntries.slice(0, 10);
  } catch(e) {}

  const children = [
    { type: "text", value: "植物大战僵尸 · 白天 1-5", size: "xl", weight: "bold" },
    { type: "text", value: "终极挑战：3 面旗 · 5 行 · 普通僵尸、路障、撑杆跳、铁桶齐上阵", size: "medium" },
    { type: "text", value: "🏆 通关排行榜", size: "large", weight: "bold" }
  ];
  if (leaderboard.length === 0) {
    children.push({ type: "text", value: "暂无通关记录，快来成为第一个通关的人！", size: "medium" });
  } else {
    leaderboard.forEach((e, i) => {
      const medal = i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : (i+1)+".";
      children.push({ type: "text", value: medal + " " + e.name + " — 通关 " + e.count + " 次", size: "medium" });
    });
  }

  children.push({ type: "text", value: "☀ 本周排行榜 · " + yearWeek + "（每周一刷新）", size: "large", weight: "bold" });
  if (weekLeaderboard.length === 0) {
    children.push({ type: "text", value: "本周暂无记录，参与「每周挑战」通关即可上榜，多打多累积！", size: "medium" });
  } else {
    weekLeaderboard.forEach((e, i) => {
      const medal = i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : (i+1)+".";
      children.push({ type: "text", value: medal + " " + e.name + " — 阳光 " + e.sun, size: "medium" });
    });
  }

  return {
    blocks: { type: "vstack", align: "center", padding: "medium", gap: "small", children },
    state: {},
    effects: []
  };
}

// 生成页面：种子注入在脚本最前面，让 newGame 能读到。
export async function webview(ctx, api) {
  const seed = ((Date.now() ^ Math.floor(Math.random() * 1e9)) >>> 0) || 1;

  // 服务端确定本周（防伪：不信任客户端）
  const yearWeek = isoWeek(new Date());
  const weeklySet = weeklyZombieSet(yearWeek);

  // 读取共享区排行榜，注入页面
  // listPublic 可能返回 {key:value} 或 [{key,value}]，两种都兼容
  let leaderboard = [];
  let weekLeaderboard = [];
  try {
    const all = await api.kv.listPublic();
    const getVal = (key) => {
      if (Array.isArray(all)) {
        const item = all.find(x => (x.key||x[0]) === key);
        return item ? (item.value ?? item[1]) : undefined;
      }
      return all[key];
    };
    const keys = Array.isArray(all) ? all.map(x => x.key || x[0]) : Object.keys(all);
    const entries = [];
    const sunEntries = [];
    const wPrefix = "wsun_" + yearWeek + "_";
    const wnPrefix = "wname_" + yearWeek + "_";
    for (const k of keys) {
      if (!k) continue;
      if (k.startsWith("clear_")) {
        const uid = k.slice(6);
        const name = getVal("name_" + uid) || "匿名玩家";
        const count = parseInt(getVal(k)) || 0;
        entries.push({ name, count });
      } else if (k.startsWith(wPrefix)) {
        const uid = k.slice(wPrefix.length);
        const name = getVal(wnPrefix + uid) || "匿名玩家";
        const sun = parseInt(getVal(k)) || 0;
        sunEntries.push({ name, sun });
      }
    }
    entries.sort((a, b) => b.count - a.count);
    leaderboard = entries.slice(0, 10);
    sunEntries.sort((a, b) => b.sun - a.sun);
    weekLeaderboard = sunEntries.slice(0, 10);
  } catch(e) {}

  const inject = "window.__SEED__=" + seed + ";window.__LEADERBOARD__=" + JSON.stringify(leaderboard) + ";window.__WEEK__=" + JSON.stringify({id:yearWeek, zombies:weeklySet}) + ";window.__WEEK_LEADERBOARD__=" + JSON.stringify(weekLeaderboard) + ";\n";
  const js = inject + GAME_JS;
  return {
    html: GAME_HTML,
    css: GAME_CSS,
    js: js,
  };
}

// 客户端通过 window.community.call("finish", {seed, actions, result}) 上报结果。
// 页面的分数不可信，这里用种子回放重算击杀数，并更新排行榜。
export async function onMessage(ctx, api) {
  if (ctx.method !== "finish") {
    return { blocks: null, state: null, effects: [] };
  }
  const { seed, actions, result, level, mode, collectedSun } = ctx.params || {};
  const kills = replay(seed, actions);
  const effects = [];

  // 个人最高击杀
  let best = 0;
  try { best = (await api.kv.get("best")) ?? 0; } catch(e) {}
  if (result === "win" && kills > best) {
    effects.push({ type: "kv.set", key: "best", value: kills });
  }

  // 通关排行榜：只有通关才记入（现在只有第五关）
  if (result === "win" && level === 0 && ctx.user) {
    try {
      let clearCount = 0;
      try { clearCount = parseInt((await api.kv.get("clears")) ?? 0) || 0; } catch(e) {}
      clearCount += 1;
      effects.push({ type: "kv.set", key: "clears", value: clearCount });
      const uid = String(ctx.user.id);
      // 官方文档：ctx.user 只含 id/username/avatar_url，username 才是真名
      const uname = ctx.user.username || ("玩家" + uid.slice(-4));
      effects.push({ type: "kv.shared.set", key: "clear_" + uid, value: String(clearCount) });
      effects.push({ type: "kv.shared.set", key: "name_" + uid, value: uname });
    } catch(e) {}
  }

  // 周阳光榜：仅 weekly 模式 + 胜利（周标识以服务端为准，防伪；collectedSun 单局上限 5000）
  if (mode === "weekly" && result === "win" && ctx.user) {
    try {
      const sun = Math.min(parseInt(collectedSun) || 0, 5000);
      if (sun > 0) {
        const serverWeek = isoWeek(new Date());
        const uid = String(ctx.user.id);
        const uname = ctx.user.username || ("玩家" + uid.slice(-4));
        const wkey = "wsun_" + serverWeek + "_" + uid;
        let prev = 0;
        try {
          const all = await api.kv.listPublic();
          const getVal = (key) => {
            if (Array.isArray(all)) { const it = all.find(x => (x.key||x[0]) === key); return it ? (it.value ?? it[1]) : undefined; }
            return all[key];
          };
          prev = parseInt(getVal(wkey)) || 0;
        } catch(e) {}
        effects.push({ type: "kv.shared.set", key: wkey, value: String(prev + sun) });
        effects.push({ type: "kv.shared.set", key: "wname_" + serverWeek + "_" + uid, value: uname });
      }
    } catch(e) {}
  }

  return { blocks: null, state: null, effects };
}

// 简化回放：用相同种子校验操作序列的合法性，统计击杀数。
// 真实场景应完整重放游戏模拟逻辑；这里校验种子有效且操作结构合法。
function replay(seed, actions) {
  if (!Number.isInteger(seed) || !Array.isArray(actions)) return 0;
  let kills = 0;
  for (const a of actions) {
    if (a && a.e === "kill") kills++;
  }
  // 击杀数上限：第三关 20 波的理论上限
  return Math.min(kills, 200);
}
